import React, { useState, useMemo, useEffect } from 'react';
import { useDropzone } from 'react-dropzone';
import { filesApi } from '../../../api/files';
import { useNavigate } from 'react-router-dom';
import 'bootstrap-icons/font/bootstrap-icons.css';
import './UploadPage.css';

const UploadPage: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [filePreview, setFilePreview] = useState<string | null>(null);
  const [ocrEngine, setOcrEngine] = useState<string>('tesseract');
  const [isWhiteboard, setIsWhiteboard] = useState<boolean>(false);
  const [isProcessing, setIsProcessing] = useState<boolean>(false);
  const [processingDetails, setProcessingDetails] = useState<string>('');
  const [isGoogleVisionAvailable, setIsGoogleVisionAvailable] = useState<boolean>(true);
  const [checkingAvailability, setCheckingAvailability] = useState<boolean>(true);
  const navigate = useNavigate();

  // Verificar disponibilidad de Google Vision API al cargar el componente
  useEffect(() => {
    const checkGoogleVision = async () => {
      try {
        setCheckingAvailability(true);
        const isAvailable = await filesApi.checkGoogleVisionAvailable();
        setIsGoogleVisionAvailable(isAvailable);
        
        // Si Google Vision no está disponible y está seleccionado, cambiar a Tesseract
        if (!isAvailable && ocrEngine === 'google') {
          setOcrEngine('tesseract');
        }
      } catch (error) {
        console.error('Error verificando Google Vision:', error);
        setIsGoogleVisionAvailable(false);
      } finally {
        setCheckingAvailability(false);
      }
    };
    
    checkGoogleVision();
  }, [ocrEngine]);

  const onDrop = useMemo(() => {
    return (acceptedFiles: File[]) => {
      if (acceptedFiles.length > 0) {
        const selectedFile = acceptedFiles[0];
        setFile(selectedFile);
        
        // Crear preview para imágenes
        if (selectedFile.type.startsWith('image/')) {
          const reader = new FileReader();
          reader.onload = () => {
            setFilePreview(reader.result as string);
          };
          reader.readAsDataURL(selectedFile);
        } else {
          // Para PDFs mostrar un icono o mensaje
          setFilePreview(null);
        }
      }
    };
  }, []);

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop,
    accept: {
      'image/*': ['.jpg', '.jpeg', '.png', '.gif', '.bmp', '.webp'],
      'application/pdf': ['.pdf'],
    },
    maxFiles: 1,
  });

  const handleProcessFile = async () => {
    if (!file) {
      alert("Por favor, seleccione un archivo para procesar.");
      return;
    }

    try {
      setIsProcessing(true);
      setProcessingDetails(
        `Utilizando ${ocrEngine === 'tesseract' ? 'Tesseract OCR' : 'Google Vision OCR'} para ${
          isWhiteboard ? 'pizarra/notas a mano' : 'documento impreso'
        }`
      );

      // Subir el archivo con opciones
      const response = await filesApi.uploadFile(file, {
        engine: ocrEngine,
        preprocessing: isWhiteboard
      });

      console.log('Respuesta del servidor:', response);

      // Redirigir según la respuesta
      if (response && response.ocr_result) {
        // Si tenemos un token de sesión o ID de resultado, redirigir a la página de previsualización
        navigate(`/ocr-preview/${response.path}`);
      } else {
        alert("El procesamiento se ha completado, pero no se ha recibido resultado OCR.");
      }
    } catch (error) {
      console.error("Error durante el procesamiento:", error);
      alert("Ha ocurrido un error durante el procesamiento del archivo.");
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="container-fluid py-4">
      <h1 className="mb-4">Extraer Texto de Imágenes y PDFs</h1>

      <div className="row">
        <div className="col-md-8">
          <div className="card mb-4">
            <div className="card-header">
              <h5 className="card-title mb-0">Subir Archivo</h5>
            </div>
            <div className="card-body">
              <div {...getRootProps({ className: 'dropzone' })}>
                <input {...getInputProps()} />
                {isDragActive ? (
                  <p className="dz-message">Suelta el archivo aquí...</p>
                ) : (
                  <p className="dz-message">
                    Arrastra un archivo aquí o haz clic para seleccionarlo<br />
                    <small>Formatos aceptados: Imágenes (JPG, PNG, etc.) y PDF</small>
                  </p>
                )}
              </div>

              {file && (
                <div className="mt-3">
                  <h6>Archivo seleccionado:</h6>
                  <p>
                    {file.name} ({Math.round(file.size / 1024)} KB)
                  </p>
                </div>
              )}

              {filePreview && (
                <img
                  src={filePreview}
                  alt="Vista previa"
                  className="file-preview mt-3 rounded mx-auto d-block"
                />
              )}
            </div>
          </div>
        </div>

        <div className="col-md-4">
          <div className="card mb-4">
            <div className="card-header">
              <h5 className="card-title mb-0">Opciones de OCR</h5>
            </div>
            <div className="card-body">
              <div className="mb-3">
                <label className="form-label">Motor de OCR:</label>
                <div className="form-check">
                  <input
                    className="form-check-input"
                    type="radio"
                    name="ocr_engine"
                    id="engine_tesseract"
                    value="tesseract"
                    checked={ocrEngine === 'tesseract'}
                    onChange={() => setOcrEngine('tesseract')}
                  />
                  <label className="form-check-label" htmlFor="engine_tesseract">
                    Tesseract OCR (gratuito, local)
                  </label>
                </div>
                <div className="form-check">
                  <input
                    className="form-check-input"
                    type="radio"
                    name="ocr_engine"
                    id="engine_google"
                    value="google"
                    checked={ocrEngine === 'google'}
                    onChange={() => setOcrEngine('google')}
                    disabled={!isGoogleVisionAvailable}
                  />
                  <label className="form-check-label" htmlFor="engine_google">
                    Google Vision API (mejor calidad)
                    {checkingAvailability && <span className="ms-2"><i className="bi bi-hourglass-split"></i></span>}
                    {!checkingAvailability && !isGoogleVisionAvailable && 
                      <span className="text-danger ms-2">(no disponible - falta archivo de credenciales)</span>}
                  </label>
                </div>
              </div>

              <div className="mb-3">
                <label className="form-label">Tipo de imagen:</label>
                <div className="form-check">
                  <input
                    className="form-check-input"
                    type="radio"
                    name="is_whiteboard"
                    id="type_document"
                    value="false"
                    checked={!isWhiteboard}
                    onChange={() => setIsWhiteboard(false)}
                  />
                  <label className="form-check-label" htmlFor="type_document">
                    Documento impreso / libro
                  </label>
                </div>
                <div className="form-check">
                  <input
                    className="form-check-input"
                    type="radio"
                    name="is_whiteboard"
                    id="type_whiteboard"
                    value="true"
                    checked={isWhiteboard}
                    onChange={() => setIsWhiteboard(true)}
                  />
                  <label className="form-check-label" htmlFor="type_whiteboard">
                    Pizarra / notas a mano
                  </label>
                </div>
              </div>

              <button
                type="button"
                className="btn btn-primary w-100"
                onClick={handleProcessFile}
                disabled={!file || isProcessing}
              >
                <i className="bi bi-gear-fill me-2"></i> Procesar Archivo
              </button>
            </div>
          </div>

          <div className="card">
            <div className="card-header">
              <h5 className="card-title mb-0">Información</h5>
            </div>
            <div className="card-body">
              <div className="mb-2">
                <p className="mb-1"><strong>Tipos de archivo soportados:</strong></p>
                <small>Imágenes: JPG, PNG, GIF, BMP, etc.</small><br />
                <small>Documentos: PDF</small>
              </div>
              <div>
                <p className="mb-1"><strong>Recomendaciones:</strong></p>
                <small>Use Tesseract para documentos simples y bien escaneados.</small><br />
                <small>Mejor calidad de OCR con Google Vision para pizarras y documentos complejos.</small>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Overlay de procesamiento */}
      {isProcessing && (
        <div className="processing-overlay">
          <div className="processing-info">
            <div className="spinner-border text-primary mb-3" role="status">
              <span className="visually-hidden">Procesando...</span>
            </div>
            <h5>Procesando Archivo</h5>
            <p>Por favor espere mientras se procesa el archivo...</p>
            <p id="processing-detail" className="text-muted">
              {processingDetails}
            </p>
          </div>
        </div>
      )}
    </div>
  );
};

export default UploadPage;
