import React, { useState, useEffect } from 'react';
import { Form, Button, Row, Col } from 'react-bootstrap';
import Select from 'react-select';
import './NoteEditForm.css';

interface Tag {
  id: number;
  name: string;
}

interface Topic {
  id: number;
  name: string;
}

interface NoteData {
  title: string;
  content: string;
  tags?: Tag[];
  topics?: Topic[];
  main_topic?: string;
  source_type?: string;
}

interface NoteEditFormProps {
  note: NoteData;
  availableTags: Tag[];
  availableTopics: Topic[];
  onSave: (noteData: NoteData) => void;
  onCancel: () => void;
}

const NoteEditForm: React.FC<NoteEditFormProps> = ({
  note,
  availableTags,
  availableTopics,
  onSave,
  onCancel
}) => {
  const [formData, setFormData] = useState<NoteData>({
    title: '',
    content: '',
    tags: [],
    topics: [],
    main_topic: '',
    source_type: 'Texto'
  });

  const sourceTypes = [
    { value: 'Texto', label: 'Texto' },
    { value: 'PDF', label: 'PDF' },
    { value: 'URL', label: 'URL' },
    { value: 'OCR', label: 'Imagen (OCR)' }
  ];

  // Convertir tags y topics para el componente Select
  const convertToOptions = (items: any[] = []) => {
    return items.map(item => ({
      value: item.id,
      label: item.name
    }));
  };

  const selectedTags = formData.tags?.map(tag => ({
    value: tag.id,
    label: tag.name
  })) || [];

  const selectedTopics = formData.topics?.map(topic => ({
    value: topic.id,
    label: topic.name
  })) || [];

  const selectedSourceType = sourceTypes.find(type => type.value === formData.source_type);

  // Inicializar form data con datos de la nota
  useEffect(() => {
    if (note) {
      setFormData({
        title: note.title || '',
        content: note.content || '',
        tags: note.tags || [],
        topics: note.topics || [],
        main_topic: note.main_topic || '',
        source_type: note.source_type || 'Texto'
      });
    }
  }, [note]);

  // Manejar cambios en el formulario
  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  // Manejar cambios en tags
  const handleTagsChange = (selectedOptions: any) => {
    const tags = selectedOptions ? selectedOptions.map((option: any) => ({
      id: option.value,
      name: option.label
    })) : [];
    
    setFormData(prev => ({
      ...prev,
      tags
    }));
  };

  // Manejar cambios en topics
  const handleTopicsChange = (selectedOptions: any) => {
    const topics = selectedOptions ? selectedOptions.map((option: any) => ({
      id: option.value,
      name: option.label
    })) : [];
    
    setFormData(prev => ({
      ...prev,
      topics
    }));
  };

  // Manejar cambios en source type
  const handleSourceTypeChange = (selectedOption: any) => {
    setFormData(prev => ({
      ...prev,
      source_type: selectedOption ? selectedOption.value : 'Texto'
    }));
  };

  // Manejar envío del formulario
  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave(formData);
  };

  return (
    <Form onSubmit={handleSubmit}>
      <Form.Group className="mb-4">
        <Form.Label htmlFor="title">Título</Form.Label>
        <Form.Control
          type="text"
          id="title"
          name="title"
          value={formData.title}
          onChange={handleChange}
          placeholder="Título de la nota"
          required
          className="form-control-lg"
        />
      </Form.Group>

      <Form.Group className="mb-4">
        <Form.Label htmlFor="content">Contenido</Form.Label>
        <Form.Control
          as="textarea"
          id="content"
          name="content"
          value={formData.content}
          onChange={handleChange}
          placeholder="Contenido de la nota (admite formato Markdown)"
          rows={12}
          required
        />
        <Form.Text className="text-muted">
          Puedes usar formato Markdown para dar estilo al texto.
        </Form.Text>
      </Form.Group>

      <Row>
        <Col md={6}>
          <Form.Group className="mb-3">
            <Form.Label htmlFor="tags">Etiquetas</Form.Label>
            <Select
              id="tags"
              isMulti
              options={convertToOptions(availableTags)}
              value={selectedTags}
              onChange={handleTagsChange}
              placeholder="Selecciona o crea etiquetas"
              className="react-select-container"
              classNamePrefix="react-select"
            />
          </Form.Group>
        </Col>
        <Col md={6}>
          <Form.Group className="mb-3">
            <Form.Label htmlFor="source_type">Tipo de Fuente</Form.Label>
            <Select
              id="source_type"
              options={sourceTypes}
              value={selectedSourceType}
              onChange={handleSourceTypeChange}
              placeholder="Selecciona el tipo de contenido"
              className="react-select-container"
              classNamePrefix="react-select"
            />
          </Form.Group>
        </Col>
      </Row>

      <Row>
        <Col md={6}>
          <Form.Group className="mb-3">
            <Form.Label htmlFor="main_topic">Tema Principal</Form.Label>
            <Form.Control
              type="text"
              id="main_topic"
              name="main_topic"
              value={formData.main_topic}
              onChange={handleChange}
              placeholder="Tema principal"
            />
          </Form.Group>
        </Col>
        <Col md={6}>
          <Form.Group className="mb-3">
            <Form.Label htmlFor="topics">Temas Relacionados</Form.Label>
            <Select
              id="topics"
              isMulti
              options={convertToOptions(availableTopics)}
              value={selectedTopics}
              onChange={handleTopicsChange}
              placeholder="Selecciona o crea temas"
              className="react-select-container"
              classNamePrefix="react-select"
            />
          </Form.Group>
        </Col>
      </Row>

      <div className="d-flex justify-content-end mt-4">
        <Button variant="outline-secondary" onClick={onCancel} className="me-2">
          Cancelar
        </Button>
        <Button variant="primary" type="submit">
          Guardar Nota
        </Button>
      </div>
    </Form>
  );
};

export default NoteEditForm;
