import React, { useState, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { notesApi } from '../../../api/notes';
import { tagsApi } from '../../../api/tags';
import { Button, Card, Container, Row, Col, Breadcrumb, Spinner, Alert } from 'react-bootstrap';
import NoteContent from '../components/NoteContent';
import NoteMetadata from '../components/NoteMetadata';
import NoteEditForm from '../components/NoteEditForm';
import TextAnalysisPanel from '../components/TextAnalysisPanel';
import TopicsPanel from '../components/TopicsPanel';
import TagsManager from '../components/TagsManager';
// Utilizamos los componentes que usan TextAnalyzer pero no lo importamos directamente
import './NoteDetailPage.css';

const NoteDetailPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  
  const [note, setNote] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [tags, setTags] = useState<any[]>([]);
  const [topics, setTopics] = useState<any[]>([]);
  // Ya no necesitamos estos estados locales pues los maneja internamente TopicsPanel
  // A través de la API de análisis

  // Cargar datos iniciales
  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);
        
        // Cargar etiquetas y temas disponibles para usar en formulario de edición
        const [tagsResponse, topicsResponse] = await Promise.all([
          tagsApi.getTags(),
          notesApi.getTopics()
        ]);
        
        setTags(tagsResponse.items || []);
        setTopics(topicsResponse.items || []);
        
        // Si tenemos un ID, cargar la nota existente
        if (id && id !== 'new') {
          const noteResponse = await notesApi.getNoteById(parseInt(id));
          setNote(noteResponse);
        } else {
          // Crear una nota vacía para el modo "nueva nota"
          setNote({
            id: null,
            title: 'Nueva Nota',
            content: '',
            summary: '',
            tags: [],
            topics: [],
            main_topic: '',
            created_at: new Date().toISOString(),
            source_type: 'Texto'
          });
          
          // Activar automáticamente el modo edición para nuevas notas
          setIsEditing(true);
        }
      } catch (err) {
        console.error('Error al cargar los datos:', err);
        setError('No se pudo cargar la nota. Verifica tu conexión e intenta nuevamente.');
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [id]);

  // Manejar el guardado de la nota
  const handleSaveNote = async (updatedNote: any) => {
    try {
      let savedNote;
      
      if (note.id) {
        // Actualizar nota existente
        savedNote = await notesApi.updateNote(note.id, updatedNote);
      } else {
        // Crear nueva nota
        savedNote = await notesApi.createNote(updatedNote);
      }
      
      setNote(savedNote);
      setIsEditing(false);
      
      // Redirigir a la página de la nota recién creada si estábamos en "nueva nota"
      if (!note.id && savedNote.id) {
        navigate(`/notes/${savedNote.id}`, { replace: true });
      }
    } catch (err) {
      console.error('Error al guardar la nota:', err);
      alert('Error al guardar la nota. Inténtalo nuevamente.');
    }
  };
  
  // Manejar actualización de etiquetas sin entrar en modo edición completa
  const handleUpdateTags = async (newTags: any[]) => {
    try {
      const updatedNote = { ...note, tags: newTags };
      const savedNote = await notesApi.updateNote(note.id, updatedNote);
      setNote(savedNote);
    } catch (err) {
      console.error('Error al actualizar etiquetas:', err);
      alert('Error al guardar las etiquetas. Inténtalo nuevamente.');
    }
  };
  
  // Manejar actualización de temas sin entrar en modo edición completa
  const handleUpdateTopics = async (mainTopic: string, newTopics: any[]) => {
    try {
      const updatedNote = { 
        ...note, 
        main_topic: mainTopic, 
        topics: newTopics 
      };
      const savedNote = await notesApi.updateNote(note.id, updatedNote);
      setNote(savedNote);
    } catch (err) {
      console.error('Error al actualizar temas:', err);
      alert('Error al guardar los temas. Inténtalo nuevamente.');
    }
  };
  
  // Crear nueva etiqueta
  const handleCreateTag = async (tagName: string) => {
    try {
      const newTag = await tagsApi.createTag(tagName);
      setTags([...tags, newTag]);
      return newTag;
    } catch (err) {
      console.error('Error al crear etiqueta:', err);
      alert('Error al crear etiqueta. Inténtalo nuevamente.');
      throw err;
    }
  };

  // Manejar la eliminación de la nota
  const handleDeleteNote = async () => {
    if (!note.id) return;
    
    if (window.confirm('¿Estás seguro de que deseas eliminar esta nota? Esta acción no se puede deshacer.')) {
      try {
        await notesApi.deleteNote(note.id);
        navigate('/notes');
      } catch (err) {
        console.error('Error al eliminar la nota:', err);
        alert('Error al eliminar la nota. Inténtalo nuevamente.');
      }
    }
  };

  // Renderizado condicional según estado de carga
  if (loading) {
    return (
      <Container fluid className="py-4">
        <div className="text-center py-5">
          <Spinner animation="border" role="status" className="mb-2">
            <span className="visually-hidden">Cargando...</span>
          </Spinner>
          <p>Cargando nota...</p>
        </div>
      </Container>
    );
  }

  if (error) {
    return (
      <Container fluid className="py-4">
        <Alert variant="danger">
          <Alert.Heading>Error</Alert.Heading>
          <p>{error}</p>
        </Alert>
      </Container>
    );
  }

  return (
    <Container fluid className="py-4">
      {/* Sección superior: Acciones y navegación */}
      <div className="d-flex justify-content-between align-items-center mb-4">
        <div>
          <Breadcrumb>
            <Breadcrumb.Item linkAs={Link} linkProps={{ to: "/dashboard" }}>Dashboard</Breadcrumb.Item>
            <Breadcrumb.Item linkAs={Link} linkProps={{ to: "/notes" }}>Notas</Breadcrumb.Item>
            <Breadcrumb.Item active>{note?.title || 'Nota'}</Breadcrumb.Item>
          </Breadcrumb>
        </div>
        <div className="d-flex">
          {!isEditing ? (
            <>
              <Button variant="primary" className="me-2" onClick={() => setIsEditing(true)}>
                <i className="fas fa-edit me-1"></i> Editar
              </Button>
              {note.id && (
                <Button variant="outline-danger" onClick={handleDeleteNote}>
                  <i className="fas fa-trash me-1"></i> Eliminar
                </Button>
              )}
            </>
          ) : (
            <Button variant="outline-secondary" onClick={() => setIsEditing(false)}>
              <i className="fas fa-times me-1"></i> Cancelar
            </Button>
          )}
        </div>
      </div>
      
      {/* Contenedor principal de la nota */}
      <Row>
        {/* Columna izquierda: Nota */}
        <Col md={8}>
          <Card className="mb-4">
            <Card.Body>
              {!isEditing ? (
                <NoteContent note={note} />
              ) : (
                <NoteEditForm 
                  note={note} 
                  availableTags={tags} 
                  availableTopics={topics} 
                  onSave={handleSaveNote} 
                  onCancel={() => setIsEditing(false)} 
                />
              )}
            </Card.Body>
          </Card>
        </Col>
        
        {/* Columna derecha: Metadatos y análisis */}
        <Col md={4}>
          {!isEditing && note?.content && (
            <TextAnalysisPanel 
              content={note.content}
            />
          )}
          
          {!isEditing && note?.id && (
            <TopicsPanel
              mainTopic={note.main_topic}
              topics={note.topics}
              availableTopics={topics}
              onSaveTopics={handleUpdateTopics}
              noteId={note.id}
              content={note.content}
            />
          )}
          
          {!isEditing && note?.id && (
            <TagsManager
              tags={note.tags || []}
              availableTags={tags}
              onSaveTags={handleUpdateTags}
              onCreateTag={handleCreateTag}
            />
          )}
          
          <NoteMetadata note={note} />
        </Col>
      </Row>
    </Container>
  );
};

export default NoteDetailPage;
