
import { useNavigate } from 'react-router-dom';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { useAuthStore } from '../../../store/authStore';
import './Auth.css';

// Esquema de validación para el formulario de login
// Definición más explícita para resolver problemas de tipo
const loginSchema = z.object({
  username: z
    .string()
    .min(1, 'El nombre de usuario es requerido'),
  password: z
    .string()
    .min(1, 'La contraseña es requerida'),
  rememberMe: z
    .boolean()
    .default(false)
});

// Tipo explícito para asegurar compatibilidad
type LoginFormValues = {
  username: string;
  password: string;
  rememberMe: boolean;
};

const LoginForm = () => {
  const navigate = useNavigate();
  const { login, error, clearError, isLoading } = useAuthStore();
  
  // Garantizar que React Hook Form use tipos compatibles
  const { register, handleSubmit, formState: { errors } } = useForm<LoginFormValues>({
    resolver: zodResolver(loginSchema) as any, // Uso de 'any' para evitar incompatibilidades de tipo
    defaultValues: {
      username: '',
      password: '',
      rememberMe: false
    }
  });
  
  const onSubmit = async (data: LoginFormValues) => {
    clearError(); // Limpiar errores previos
    console.log('Iniciando intento de login con:', { username: data.username, rememberMe: data.rememberMe });
    
    try {
      console.log('Llamando a función login del authStore...');
      await login(data.username, data.password, data.rememberMe);
      console.log('Login completado con éxito, esperando redirección...');
      // Si el login es exitoso, el useEffect en el componente Login redirigirá al dashboard
    } catch (error) {
      console.error('Error durante el login:', error);
    }
  };
  
  return (
    <div className="login-form">
      <h2>Iniciar Sesión</h2>
      
      {error && (
        <div className="error-message">
          {error}
          <button onClick={clearError} className="close-btn">×</button>
        </div>
      )}
      
      <form onSubmit={(e) => {
          e.preventDefault();
          console.log('Formulario enviado');
          handleSubmit(onSubmit)(e);
        }}>
        <div className="form-group">
          <label htmlFor="username">Nombre de usuario</label>
          <input
            id="username"
            type="text"
            {...register('username')}
            className={errors.username ? 'input-error' : ''}
            placeholder="Ingrese su nombre de usuario"
          />
          {errors.username && <span className="error">{errors.username.message}</span>}
        </div>
        
        <div className="form-group">
          <label htmlFor="password">Contraseña</label>
          <input
            id="password"
            type="password"
            {...register('password')}
            className={errors.password ? 'input-error' : ''}
            placeholder="Ingrese su contraseña"
          />
          {errors.password && <span className="error">{errors.password.message}</span>}
        </div>
        
        <div className="form-group checkbox">
          <input
            id="rememberMe"
            type="checkbox"
            {...register('rememberMe')}
          />
          <label htmlFor="rememberMe">Recordarme</label>
        </div>
        
        <div className="form-actions">
          <button 
            type="submit" 
            disabled={isLoading}
            className="btn-primary"
          >
            {isLoading ? 'Iniciando sesión...' : 'Iniciar Sesión'}
          </button>
        </div>
        
        <div className="links">
          <p>
            <a href="#" onClick={(e) => { e.preventDefault(); navigate('/recover-password'); }}>
              ¿Olvidaste tu contraseña?
            </a>
          </p>
          <p>
            ¿No tienes una cuenta? <a href="#" onClick={(e) => { e.preventDefault(); navigate('/register'); }}>Registrarse</a>
          </p>
        </div>
      </form>
    </div>
  );
};

export default LoginForm;
