import React, { useState, useEffect } from 'react';
import { Card, Badge, Button, ProgressBar, Spinner } from 'react-bootstrap';
import type { TextStats, KeyConcept } from '../../../api/analysis';
import { analysisApi } from '../../../api/analysis';
import './TextAnalysisPanel.css';

interface TextAnalysisPanelProps {
  content: string;
  onRefreshAnalysis?: () => void;
}

const TextAnalysisPanel: React.FC<TextAnalysisPanelProps> = ({ content, onRefreshAnalysis }) => {
  const [showAnalysis, setShowAnalysis] = useState<boolean>(true);
  const [textStats, setTextStats] = useState<TextStats>({ words: 0, paragraphs: 0, reading_time: 0, readability: 0 });
  const [tone, setTone] = useState<string>('Neutral');
  const [concepts, setConcepts] = useState<KeyConcept[]>([]);
  const [readabilityLabel, setReadabilityLabel] = useState<string>('Calculando...');
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  // Función para analizar texto usando la API
  const analyzeTextContent = async (textContent: string) => {
    if (!textContent || textContent.trim().length < 10) {
      setTextStats({ words: 0, paragraphs: 0, reading_time: 0, readability: 0 });
      setTone('Neutral');
      setConcepts([]);
      setReadabilityLabel('No disponible');
      return;
    }
    
    setLoading(true);
    setError(null);
    
    try {
      const analysis = await analysisApi.analyzeText(textContent);
      
      setTextStats(analysis.stats);
      setTone(analysis.tone);
      setConcepts(analysis.concepts);
      setReadabilityLabel(analysis.readability_label);
    } catch (err) {
      console.error('Error al obtener análisis de texto:', err);
      setError('No se pudo analizar el texto');
    } finally {
      setLoading(false);
    }
  };
  
  // Analizar texto cuando cambia el contenido
  useEffect(() => {
    analyzeTextContent(content);
  }, [content]);
  
  // Manejar actualización manual del análisis
  const handleRefreshAnalysis = () => {
    analyzeTextContent(content);
    if (onRefreshAnalysis) {
      onRefreshAnalysis();
    }
  };

  // Obtener color para la barra de progreso basado en la puntuación de legibilidad
  const getReadabilityVariant = (score: number): string => {
    if (score >= 80) return 'success';
    if (score >= 60) return 'info';
    if (score >= 40) return 'warning';
    return 'danger';
  };

  // Obtener color para el indicador de tono
  const getToneColor = (): string => {
    switch (tone.toLowerCase()) {
      case 'formal': return '#7048e8';
      case 'academic': return '#2b6cb0';
      case 'technical': return '#0986c3';
      case 'informal': return '#38a169';
      case 'emotional': return '#e53e3e';
      default: return '#718096';
    }
  };

  return (
    <Card className="mb-4">
      <Card.Header className="d-flex justify-content-between align-items-center">
        <h5 className="mb-0">Análisis de Resumen</h5>
        <div>
          <Button 
            size="sm" 
            variant="outline-primary"
            className="me-2"
            title="Regenerar análisis"
            onClick={handleRefreshAnalysis}
            disabled={loading}
          >
            {loading ? <Spinner as="span" animation="border" size="sm" /> : <i className="fas fa-sync-alt"></i>}
          </Button>
          <Button 
            variant="link" 
            className="p-0 border-0 card-toggle" 
            onClick={() => setShowAnalysis(!showAnalysis)}
            aria-expanded={showAnalysis}
          >
            <i className={`fas fa-chevron-${showAnalysis ? 'up' : 'down'}`}></i>
          </Button>
        </div>
      </Card.Header>
      
      {showAnalysis && (
        <Card.Body>
          {error && (
            <div className="alert alert-danger" role="alert">
              {error}
            </div>
          )}
          
          {/* Conceptos clave */}
          <div className="mb-3">
            <h6><i className="fas fa-lightbulb"></i> Conceptos Clave</h6>
            <div className="d-flex flex-wrap gap-1 mt-2">
              {content && content.length > 0 ? (
                concepts.map((concept, index) => (
                  <Badge bg="info" className="me-1 mb-1" key={index}>
                    {concept.concept}
                  </Badge>
                ))
              ) : (
                <span className="text-muted">No hay suficiente texto para extraer conceptos</span>
              )}
            </div>
          </div>
          
          {/* Estadísticas de texto */}
          <div className="mb-3">
            <h6><i className="fas fa-chart-bar"></i> Estadísticas de Texto</h6>
            <div className="row text-stats mt-2">
              <div className="col-6">
                <small className="text-muted">Legibilidad:</small>
                <ProgressBar 
                  now={textStats.readability} 
                  variant={getReadabilityVariant(textStats.readability)}
                  style={{ height: '8px' }}
                  className="mt-1"
                />
                <small className="d-block mt-1">{readabilityLabel}</small>
              </div>
              <div className="col-6">
                <small className="text-muted">Tono:</small>
                <div className="d-flex align-items-center mt-1">
                  <div 
                    className="tone-indicator" 
                    style={{ 
                      backgroundColor: getToneColor(),
                      width: '12px',
                      height: '12px',
                      borderRadius: '50%',
                      display: 'inline-block',
                      marginRight: '6px'
                    }}
                  ></div>
                  <span>{tone}</span>
                </div>
              </div>
            </div>
            <div className="row text-stats mt-3">
              <div className="col-4">
                <small className="text-muted">Palabras:</small>
                <div className="fw-bold">{textStats.words}</div>
              </div>
              <div className="col-4">
                <small className="text-muted">Párrafos:</small>
                <div className="fw-bold">{textStats.paragraphs}</div>
              </div>
              <div className="col-4">
                <small className="text-muted">Tiempo lectura:</small>
                <div className="fw-bold">{textStats.reading_time} min</div>
              </div>
            </div>
          </div>
        </Card.Body>
      )}
    </Card>
  );
};

export default TextAnalysisPanel;
