import React from 'react';
import { Link } from 'react-router-dom';
import { Card, Badge, Button, OverlayTrigger, Tooltip } from 'react-bootstrap';
import './NoteCard.css';

export interface NoteCardProps {
  id: number;
  title: string;
  content: string;
  summary?: string;
  created_at: string;
  updated_at: string;
  user_id?: number;
  main_topic?: string;
  source_type?: string;
  tags?: { id: number; name: string }[];
  thumbnail_url?: string;
  onDelete?: (id: number) => void;
}

interface NoteCardComponentProps {
  note: NoteCardProps;
  viewMode: 'grid' | 'list';
  onDelete?: (id: number) => void;
}

const NoteCard: React.FC<NoteCardComponentProps> = ({ 
  note, 
  viewMode, 
  onDelete 
}) => {
  // Formatear fecha para mostrar de forma legible
  const formatDate = (dateString: string): string => {
    const date = new Date(dateString);
    return date.toLocaleDateString('es-ES', {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    });
  };

  // Truncar texto para mostrar un resumen
  const truncateText = (text: string, maxLength: number = 150): string => {
    if (!text) return 'Sin contenido';
    if (text.length <= maxLength) return text;
    
    // Buscar el último espacio antes del maxLength para cortar en palabras completas
    const lastSpace = text.substring(0, maxLength).lastIndexOf(' ');
    const truncateAt = lastSpace > 0 ? lastSpace : maxLength;
    return text.substring(0, truncateAt) + '...';
  };
  
  // Obtener un color de tema basado en el nombre
  const getTopicColor = (topic?: string): string => {
    if (!topic) return '#b2bec3'; // Color por defecto
    
    const colors: Record<string, string> = {
      'Informática': '#6c5ce7',
      'Tecnología': '#0984e3',
      'Matemáticas': '#e17055',
      'Física': '#00b894',
      'Química': '#fdcb6e',
      'Biología': '#00cec9',
      'Historia': '#d63031',
      'Geografía': '#74b9ff',
      'Literatura': '#a29bfe',
      'Filosofía': '#636e72',
      'Economía': '#00b5ad',
      'Arte': '#e84393',
      'Música': '#6c5ce7',
      'Deportes': '#e67e22',
      'Salud': '#badc58',
      'Psicología': '#ff7675',
      'Estadística': '#ff9ff3',
      'Otro': '#b2bec3'
    };
    
    return colors[topic] || colors['Otro'];
  };

  // Confirmar eliminación antes de llamar a la función onDelete
  const handleDelete = () => {
    if (window.confirm('¿Estás seguro de que deseas eliminar esta nota?')) {
      onDelete?.(note.id);
    }
  };

  return (
    <Card 
      className={`note-card ${viewMode === 'list' ? 'list-view-card' : ''}`} 
      aria-label={`Nota: ${note.title || 'Sin título'}`}
    >
      <Card.Header className="d-flex justify-content-between align-items-center">
        {note.main_topic && (
          <Badge 
            pill 
            style={{ 
              backgroundColor: getTopicColor(note.main_topic),
              marginRight: '8px' 
            }}
          >
            {note.main_topic}
          </Badge>
        )}
        <h5 className="note-title mb-0">{note.title || 'Sin título'}</h5>
        <div className="note-actions">
          <OverlayTrigger
            placement="top"
            overlay={<Tooltip id={`tooltip-view-${note.id}`}>Ver nota</Tooltip>}
          >
            <Link to={`/notes/${note.id}`}>
              <Button 
                variant="link" 
                size="sm"
                className="icon-btn"
                aria-label="Ver nota"
              >
                <i className="fas fa-eye"></i>
              </Button>
            </Link>
          </OverlayTrigger>
          
          <OverlayTrigger
            placement="top"
            overlay={<Tooltip id={`tooltip-edit-${note.id}`}>Editar nota</Tooltip>}
          >
            <Link to={`/notes/edit/${note.id}`}>
              <Button 
                variant="link" 
                size="sm"
                className="icon-btn"
                aria-label="Editar nota"
              >
                <i className="fas fa-edit"></i>
              </Button>
            </Link>
          </OverlayTrigger>
          
          {onDelete && (
            <OverlayTrigger
              placement="top"
              overlay={<Tooltip id={`tooltip-delete-${note.id}`}>Eliminar nota</Tooltip>}
            >
              <Button 
                variant="link" 
                size="sm" 
                className="icon-btn text-danger"
                onClick={handleDelete}
                aria-label="Eliminar nota"
              >
                <i className="fas fa-trash-alt"></i>
              </Button>
            </OverlayTrigger>
          )}
        </div>
      </Card.Header>
      
      <Link to={`/notes/${note.id}`} className="note-link" aria-label={`Ver nota ${note.title || 'Sin título'}`}>
        {note.thumbnail_url && (
          <div 
            className="note-thumbnail" 
            style={{ backgroundImage: `url(${note.thumbnail_url})` }}
            role="img"
            aria-label="Miniatura de la nota"
          />
        )}
        
        <Card.Body>
          <div className="note-summary">
            {note.summary || truncateText(note.content) || 'Sin contenido'}
          </div>
          
          <div className="note-tags mt-3">
            {note.tags?.map(tag => (
              <Badge 
                key={tag.id} 
                pill 
                bg="light" 
                text="dark"
                className="me-1 mb-1"
              >
                {tag.name}
              </Badge>
            ))}
          </div>
        </Card.Body>
      </Link>
      
      <Card.Footer>
        <div className="note-meta">
          <span title={`Creado el ${new Date(note.created_at).toLocaleString()}`}>
            <i className="fas fa-calendar-alt me-1" aria-hidden="true"></i>
            <span className="visually-hidden">Fecha:</span>
            {formatDate(note.created_at)}
          </span>
          <span>
            <i className="fas fa-file-alt me-1" aria-hidden="true"></i>
            <span className="visually-hidden">Tipo:</span>
            {note.source_type || 'Texto'}
          </span>
        </div>
      </Card.Footer>
    </Card>
  );
};

export default NoteCard;
