import apiClient from './client';
import type { GraphNode, GraphData } from '../features/graph/types/graph.types';

interface GraphFilters {
  nodeTypes?: string[];
  edgeTypes?: string[];
  limit?: number;
  depth?: number;
  rootNodeId?: string | number;
}

export const graphApi = {
  getFullGraph: async () => {
    const response = await apiClient.get('/graph/visualization');
    return response.data as GraphData;
  },
  
  getFilteredGraph: async (filters: GraphFilters) => {
    const response = await apiClient.get('/graph/filter', { params: filters });
    return response.data as GraphData;
  },
  
  getNodeById: async (nodeId: string | number) => {
    const response = await apiClient.get(`/graph/node/${nodeId}`);
    return response.data as GraphNode;
  },
  
  getNodeNeighbors: async (nodeId: string | number, depth: number = 1) => {
    const response = await apiClient.get(`/graph/neighbors/${nodeId}`, {
      params: { depth }
    });
    return response.data as GraphData;
  },
  
  searchNodes: async (query: string) => {
    const response = await apiClient.get('/graph/search', {
      params: { q: query }
    });
    return response.data as GraphNode[];
  },
  
  createNode: async (label: string, type: string, properties: Record<string, any> = {}) => {
    const response = await apiClient.post('/graph/node', {
      label,
      type,
      properties
    });
    return response.data as GraphNode;
  },
  
  updateNode: async (nodeId: string | number, properties: Record<string, any>) => {
    const response = await apiClient.put(`/graph/node/${nodeId}`, properties);
    return response.data as GraphNode;
  },
  
  deleteNode: async (nodeId: string | number) => {
    const response = await apiClient.delete(`/graph/node/${nodeId}`);
    return response.data;
  },
  
  createEdge: async (sourceId: string | number, targetId: string | number, label: string, properties: Record<string, any> = {}) => {
    const response = await apiClient.post('/graph/edge', {
      source: sourceId,
      target: targetId,
      label,
      properties
    });
    return response.data;
  },
  
  updateEdge: async (edgeId: string | number, properties: Record<string, any>) => {
    const response = await apiClient.put(`/graph/edge/${edgeId}`, properties);
    return response.data;
  },
  
  deleteEdge: async (edgeId: string | number) => {
    const response = await apiClient.delete(`/graph/edge/${edgeId}`);
    return response.data;
  },
  
  getGraphStatistics: async () => {
    const response = await apiClient.get('/graph/statistics');
    return response.data;
  }
};
