import React, { useState, useEffect } from 'react';
import { Outlet, useNavigate, Link } from 'react-router-dom';
import { useAuthStore } from '../store/authStore';
import { tagsApi } from '../api/tags';
import '../styles/AppLayout.css';

interface Tag {
  id: number;
  name: string;
  count?: number;
}

const AppLayout: React.FC = () => {
  const { user, logout } = useAuthStore();
  const navigate = useNavigate();
  const [sidebarOpen, setSidebarOpen] = useState(window.innerWidth > 768);
  const [tags, setTags] = useState<Tag[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const fetchTags = async () => {
      try {
        setIsLoading(true);
        const response = await tagsApi.getPopularTags(10);
        setTags(response.tags || []);
      } catch (error) {
        console.error('Error al cargar etiquetas:', error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchTags();
  }, []);

  const handleLogout = async () => {
    try {
      await logout();
      navigate('/login');
    } catch (error) {
      console.error('Error al cerrar sesión:', error);
    }
  };

  const toggleSidebar = () => {
    setSidebarOpen(!sidebarOpen);
  };

  return (
    <div className="app-container">
      {/* Sidebar */}
      <div className={`sidebar ${sidebarOpen ? 'open' : 'closed'}`}>
        <div className="sidebar-logo">
          <h4>Proyecto Apuntes</h4>
        </div>
        <div className="sidebar-nav">
          <ul className="nav flex-column">
            <li className="nav-item">
              <Link className="nav-link" to="/dashboard">
                <i className="fas fa-home"></i> Dashboard
              </Link>
            </li>
            <li className="nav-item">
              <Link className="nav-link" to="/notes">
                <i className="fas fa-sticky-note"></i> Mis Notas
              </Link>
            </li>
            <li className="nav-item">
              <Link className="nav-link" to="/graph">
                <i className="fas fa-project-diagram"></i> Mapa Mental
              </Link>
            </li>
            <li className="nav-item">
              <Link className="nav-link" to="/upload">
                <i className="fas fa-cloud-upload-alt"></i> Subir Imagen/PDF
              </Link>
            </li>
          </ul>
          <hr />
          <h6 className="sidebar-heading px-3 mt-4 mb-2 text-muted">
            <span>Etiquetas</span>
          </h6>
          <ul className="nav flex-column" id="tags-list">
            {isLoading ? (
              <li className="nav-item">
                <span className="nav-link">
                  <i className="fas fa-spinner fa-spin"></i> Cargando...
                </span>
              </li>
            ) : tags.length > 0 ? (
              tags.map((tag) => (
                <li className="nav-item" key={tag.id}>
                  <Link className="nav-link" to={`/notes?tags=${tag.name}`}>
                    <i className="fas fa-tag"></i> {tag.name}
                    {tag.count && <span className="badge bg-light text-dark ms-1">{tag.count}</span>}
                  </Link>
                </li>
              ))
            ) : (
              <li className="nav-item">
                <span className="nav-link">
                  <i className="fas fa-info-circle"></i> No hay etiquetas
                </span>
              </li>
            )}
          </ul>
        </div>
      </div>

      {/* Contenido principal */}
      <div className="main-content">
        {/* Header */}
        <div className="header">
          <button id="sidebar-toggle" className="btn btn-link d-md-none" onClick={toggleSidebar}>
            <i className={`fas ${sidebarOpen ? 'fa-times' : 'fa-bars'}`}></i>
          </button>
          <div className="ms-auto d-flex">
            <div className="dropdown">
              <button 
                className="btn btn-link dropdown-toggle" 
                type="button" 
                id="userDropdown" 
                data-bs-toggle="dropdown"
              >
                <i className="fas fa-user-circle"></i>
                <span className="ms-2 d-none d-md-inline">{user?.username || 'Usuario'}</span>
              </button>
              <ul className="dropdown-menu dropdown-menu-end">
                <li><Link className="dropdown-item" to="/profile">Perfil</Link></li>
                <li><Link className="dropdown-item" to="/setup-security-question">Configuración de seguridad</Link></li>
                <li><hr className="dropdown-divider" /></li>
                <li>
                  <button 
                    className="dropdown-item" 
                    onClick={handleLogout}
                  >
                    Cerrar sesión
                  </button>
                </li>
              </ul>
            </div>
          </div>
        </div>

        {/* Contenido de la página (Outlet renderizará la ruta anidada) */}
        <div className="page-content">
          <Outlet />
        </div>
      </div>
    </div>
  );
};

export default AppLayout;
