import React, { useState } from 'react';
import { Card, Badge, Button } from 'react-bootstrap';
import './NoteMetadata.css';

interface NoteMetadataProps {
  note: {
    id?: number;
    summary?: string;
    tags?: Array<{ id: number; name: string }>;
    topics?: Array<{ id: number; name: string }>;
    main_topic?: string;
    related_notes?: Array<{ id: number; title: string }>;
    ai_keywords?: Array<string>;
    ai_entities?: Array<{ name: string; type: string }>;
    ai_sentiment?: { score: number; label: string };
    ai_analysis_ready?: boolean;
  };
}

const NoteMetadata: React.FC<NoteMetadataProps> = ({ note }) => {
  const [showAIAnalysis, setShowAIAnalysis] = useState(true);

  return (
    <>
      {/* Panel de análisis y resumen */}
      <Card className="mb-4">
        <Card.Header className="d-flex justify-content-between align-items-center">
          <h5 className="mb-0">Análisis de Resumen</h5>
          <div>
            <Button 
              variant="link" 
              className="p-0 border-0 card-toggle" 
              onClick={() => setShowAIAnalysis(!showAIAnalysis)}
              aria-expanded={showAIAnalysis}
            >
              <i className={`fas fa-chevron-${showAIAnalysis ? 'up' : 'down'}`}></i>
            </Button>
          </div>
        </Card.Header>
        
        {showAIAnalysis && (
          <Card.Body>
            <div className="summary-section">
              <h6 className="section-title">Resumen</h6>
              {note.summary ? (
                <p>{note.summary}</p>
              ) : (
                <p className="text-muted">No hay resumen disponible</p>
              )}
            </div>
            
            {note.ai_keywords && note.ai_keywords.length > 0 && (
              <div className="keywords-section mt-3">
                <h6 className="section-title">Palabras Clave</h6>
                <div>
                  {note.ai_keywords.map((keyword, index) => (
                    <Badge bg="info" className="me-1 mb-1" key={index}>
                      {keyword}
                    </Badge>
                  ))}
                </div>
              </div>
            )}
            
            {note.ai_entities && note.ai_entities.length > 0 && (
              <div className="entities-section mt-3">
                <h6 className="section-title">Entidades Detectadas</h6>
                <div>
                  {note.ai_entities.map((entity, index) => (
                    <Badge bg="secondary" className="me-1 mb-1" key={index} title={`Tipo: ${entity.type}`}>
                      {entity.name}
                    </Badge>
                  ))}
                </div>
              </div>
            )}
            
            {note.ai_sentiment && (
              <div className="sentiment-section mt-3">
                <h6 className="section-title">Análisis de Sentimiento</h6>
                <div className="d-flex align-items-center">
                  <div 
                    className={`sentiment-indicator ${
                      note.ai_sentiment.label === 'positive' ? 'positive' : 
                      note.ai_sentiment.label === 'negative' ? 'negative' : 'neutral'
                    }`}
                  ></div>
                  <span className="ms-2">
                    {note.ai_sentiment.label === 'positive' ? 'Positivo' : 
                     note.ai_sentiment.label === 'negative' ? 'Negativo' : 'Neutral'} 
                    ({(note.ai_sentiment.score * 100).toFixed(1)}%)
                  </span>
                </div>
              </div>
            )}
            
            {!note.ai_analysis_ready && note.id && (
              <div className="mt-3">
                <Button variant="outline-primary" size="sm" className="w-100">
                  <i className="fas fa-magic me-1"></i> Generar Análisis IA
                </Button>
              </div>
            )}
          </Card.Body>
        )}
      </Card>
      
      {/* Panel de clasificación y tags */}
      <Card className="mb-4">
        <Card.Header>
          <h5 className="mb-0">Clasificación</h5>
        </Card.Header>
        <Card.Body>
          <div className="topics-section">
            <h6 className="section-title">Tema Principal</h6>
            <p className="main-topic">
              {note.main_topic || <span className="text-muted">Sin tema principal</span>}
            </p>
          </div>
          
          <div className="topics-section mt-3">
            <h6 className="section-title">Temas Relacionados</h6>
            {note.topics && note.topics.length > 0 ? (
              <div className="topics-list">
                {note.topics.map((topic) => (
                  <Badge bg="primary" className="me-1 mb-1" key={topic.id}>
                    {topic.name}
                  </Badge>
                ))}
              </div>
            ) : (
              <p className="text-muted">No hay temas relacionados</p>
            )}
          </div>
          
          <div className="tags-section mt-3">
            <h6 className="section-title">Etiquetas</h6>
            {note.tags && note.tags.length > 0 ? (
              <div className="tags-list">
                {note.tags.map((tag) => (
                  <Badge bg="secondary" className="me-1 mb-1" key={tag.id}>
                    {tag.name}
                  </Badge>
                ))}
              </div>
            ) : (
              <p className="text-muted">No hay etiquetas</p>
            )}
          </div>
        </Card.Body>
      </Card>
      
      {/* Panel de notas relacionadas */}
      {note.related_notes && note.related_notes.length > 0 && (
        <Card className="mb-4">
          <Card.Header>
            <h5 className="mb-0">Notas Relacionadas</h5>
          </Card.Header>
          <Card.Body>
            <ul className="related-notes-list">
              {note.related_notes.map((relatedNote) => (
                <li key={relatedNote.id}>
                  <a href={`/notes/${relatedNote.id}`}>{relatedNote.title}</a>
                </li>
              ))}
            </ul>
          </Card.Body>
        </Card>
      )}
    </>
  );
};

export default NoteMetadata;
