import React, { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Container, Row, Col, Card, Button, Form, Badge, Alert, Spinner } from 'react-bootstrap';
import { filesApi } from '../../../api/files';
import { analysisApi } from '../../../api/analysis';
import type { OcrResult } from '../../../types/files';
import './OcrPreviewPage.css';

// Definición de tipos porque TypeScript no encuentra los módulos originales
interface TextStats {
  words: number;
  paragraphs: number;
  sentences: number;
  reading_time: number;
  characters: number;
}

interface Concept {
  concept: string;
  frequency: number;
  relevance?: number;
}

interface TextAnalysisResponse {
  stats: TextStats;
  summary: string;
  concepts: Concept[];
  tone: string;
  readability_score: number;
  readability_label: string;
}

interface TopicItem {
  topic: string;
  percentage: number;
}

interface TopicsAnalysisResponse {
  main_topic: string;
  main_topic_confidence: number;
  topics_distribution: TopicItem[];
}

const OcrPreviewPage: React.FC = () => {
  const { fileId } = useParams<{ fileId: string }>();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [ocrResult, setOcrResult] = useState<OcrResult | null>(null);
  const [noteText, setNoteText] = useState<string>('');
  const [noteTitle, setNoteTitle] = useState<string>('');
  const [textAnalysis, setTextAnalysis] = useState<TextAnalysisResponse | null>(null);
  const [textAnalysisLoading, setTextAnalysisLoading] = useState(false);
  const [topicsAnalysis, setTopicsAnalysis] = useState<TopicsAnalysisResponse | null>(null);
  const [topicsLoading, setTopicsLoading] = useState(false);
  const [isWhiteboard, setIsWhiteboard] = useState(false);
  const [creatingNote, setCreatingNote] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);
  const navigate = useNavigate();
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    const fetchOcrResult = async () => {
      try {
        if (!fileId) {
          setError("No se especificó un ID de archivo para procesar");
          setLoading(false);
          return;
        }
        
        // Obtener resultados del OCR
        const result = await filesApi.processOCR(fileId, {});
        
        if (result && result.text) {
          setOcrResult(result);
          
          // Guardar el texto para edición
          setNoteText(result.text);
          
          // Establecer el título sugerido basado en el nombre del archivo
          const suggestedTitle = result.filename ? 
            result.filename.split('.').slice(0, -1).join('.') : 
            'Documento OCR';
          
          setNoteTitle(suggestedTitle);
          
          // Analizar el texto automáticamente
          await analyzeTextContent(result.text);
          await analyzeTopics(result.text);
          
          setLoading(false);
        } else {
          setError("No se pudo extraer texto del archivo");
        }
      } catch (err: unknown) {
        console.error("Error al obtener resultados OCR:", err);
        setError("Error al procesar el archivo");
        setLoading(false);
      }
    };
    
    fetchOcrResult();
  }, [fileId]);
  
  // Función para analizar el texto
  const analyzeTextContent = async (text: string) => {
    if (!text.trim()) return;
    
    setTextAnalysisLoading(true);
    
    try {
      const analysisResult = await analysisApi.analyzeText(text);
      setTextAnalysis(analysisResult as unknown as TextAnalysisResponse);
    } catch (error) {
      console.error('Error al analizar el texto:', error);
      setError('No se pudo analizar el texto. Por favor, inténtelo de nuevo.');
    } finally {
      setTextAnalysisLoading(false);
    }
  };
  
  // Función para analizar temas
  const analyzeTopics = async (text: string) => {
    if (!text.trim()) return;
    
    setTopicsLoading(true);
    
    try {
      const topicsResult = await analysisApi.analyzeTopics(text);
      setTopicsAnalysis(topicsResult as unknown as TopicsAnalysisResponse);
    } catch (error) {
      console.error('Error al analizar los temas:', error);
      // No mostramos el error al usuario para no sobrecargarlo con mensajes
    } finally {
      setTopicsLoading(false);
    }
  };
  
  // Función para copiar texto
  const handleCopyText = () => {
    if (textareaRef.current) {
      textareaRef.current.select();
      document.execCommand('copy');
      setCopySuccess(true);
      
      // Resetear el estado de copia después de un tiempo
      setTimeout(() => {
        setCopySuccess(false);
      }, 2000);
    }
  };

  // Función para crear una nota desde el OCR
  const handleCreateNote = async () => {
    if (!noteText || !noteTitle.trim()) return;
    
    setCreatingNote(true);
    
    try {
      // Incluir opciones adicionales en la creación de la nota
      const options = {
        is_whiteboard: isWhiteboard,
        summary: textAnalysis?.summary || '',
        main_topic: topicsAnalysis?.main_topic || ''
      };
      
      // Usar texto editable y opciones
      const result = await filesApi.createNoteFromOCR(noteText, noteTitle, options);
      
      // Navegar a la página de la nota creada
      navigate(`/notes/${result.id}`);
    } catch (err) {
      console.error('Error al crear la nota:', err);
      setError('No se pudo crear la nota. Por favor, inténtelo de nuevo.');
      setCreatingNote(false);
    }
  };
  
  // Re-analizar cuando cambia el texto considerablemente
  useEffect(() => {
    // Usar un timer para evitar análisis continuos mientras se escribe
    const timer = setTimeout(() => {
      if (noteText && ocrResult?.text && Math.abs(noteText.length - ocrResult.text.length) > 20) {
        analyzeTextContent(noteText);
      }
    }, 1000);
    
    return () => clearTimeout(timer);
  }, [noteText]);

  if (loading) {
    return (
      <Container fluid className="py-4">
        <div className="d-flex justify-content-center align-items-center" style={{ minHeight: '50vh' }}>
          <Spinner animation="border" variant="primary" />
          <span className="ms-3">Obteniendo resultados OCR...</span>
        </div>
      </Container>
    );
  }

  if (error) {
    return (
      <Container fluid className="py-4">
        <Alert variant="danger">
          <Alert.Heading>Error</Alert.Heading>
          <p>{error}</p>
          <hr />
          <div className="d-flex justify-content-end">
            <Button 
              variant="outline-danger"
              onClick={() => navigate('/upload')}
            >
              Volver a la página de carga
            </Button>
          </div>
        </Alert>
      </Container>
    );
  }

  return (
    <Container fluid className="py-4">
      <h1 className="mb-4">Resultados del OCR</h1>
      
      <Row>
        {/* Columna principal con texto OCR y análisis */}
        <Col md={8}>
          {/* Panel de texto OCR editable */}
          <Card className="mb-4">
            <Card.Header className="d-flex align-items-center justify-content-between">
              <h5 className="mb-0">Texto Extraído</h5>
              <div>
                {ocrResult && (
                  <Badge bg="info" className="me-2">
                    Confianza: {Math.round(ocrResult.confidence)}%
                  </Badge>
                )}
                <Button
                  variant="outline-secondary"
                  size="sm"
                  onClick={handleCopyText}
                  disabled={!noteText}
                >
                  {copySuccess ? (
                    <><i className="fas fa-check"></i> Copiado</>
                  ) : (
                    <><i className="fas fa-copy"></i> Copiar</>  
                  )}
                </Button>
              </div>
            </Card.Header>
            <Card.Body>
              <Form.Control 
                as="textarea"
                ref={textareaRef}
                value={noteText}
                onChange={(e) => setNoteText(e.target.value)}
                rows={10}
                className="mb-3"
              />
            </Card.Body>
          </Card>
          
          {/* Panel de resumen y estadísticas */}
          {textAnalysis && (
            <Card className="mb-4">
              <Card.Header>
                <h5 className="mb-0">Análisis de Texto</h5>
              </Card.Header>
              <Card.Body>
                <Row>
                  <Col md={6}>
                    <h6>Estadísticas</h6>
                    <ul className="list-unstyled">
                      <li><strong>Palabras:</strong> {textAnalysis.stats.words}</li>
                      <li><strong>Párrafos:</strong> {textAnalysis.stats.paragraphs}</li>
                      <li><strong>Tiempo de lectura:</strong> {textAnalysis.stats.reading_time} min</li>
                    </ul>
                  </Col>
                  <Col md={6}>
                    <h6>Tono y Legibilidad</h6>
                    <Badge bg="primary" className="me-2 mb-2">{textAnalysis.tone}</Badge>
                    <Badge bg="secondary">{textAnalysis.readability_label}</Badge>
                  </Col>
                </Row>
                
                {textAnalysis.concepts.length > 0 && (
                  <div className="mt-3">
                    <h6>Conceptos clave</h6>
                    <div>
                      {textAnalysis.concepts.map((concept: { concept: string; frequency: number }, idx: number) => (
                        <Badge 
                          bg="light" 
                          text="dark" 
                          className="me-2 mb-2" 
                          key={idx}
                        >
                          {concept.concept} ({concept.frequency})
                        </Badge>
                      ))}
                    </div>
                  </div>
                )}
              </Card.Body>
            </Card>
          )}
          
          {/* Panel de tópicos */}
          {topicsAnalysis && topicsAnalysis.topics_distribution.length > 0 && (
            <Card className="mb-4">
              <Card.Header>
                <h5 className="mb-0">Temas Relacionados</h5>
              </Card.Header>
              <Card.Body>
                {topicsAnalysis.main_topic && (
                  <div className="mb-3">
                    <h6>Tema principal</h6>
                    <Badge bg="success" style={{ fontSize: '1rem' }}>
                      {topicsAnalysis.main_topic} ({Math.round(topicsAnalysis.main_topic_confidence * 100)}%)
                    </Badge>
                  </div>
                )}
                
                {topicsAnalysis.topics_distribution.length > 0 && (
                  <div>
                    <h6>Distribución de temas</h6>
                    <div>
                      {topicsAnalysis.topics_distribution.map((topic: { topic: string; percentage: number }, idx: number) => (
                        <Badge 
                          bg="info" 
                          className="me-2 mb-2" 
                          key={idx}
                        >
                          {topic.topic} ({Math.round(topic.percentage * 100)}%)
                        </Badge>
                      ))}
                    </div>
                  </div>
                )}
              </Card.Body>
            </Card>
          )}
        </Col>
        
        {/* Columna lateral */}
        <Col md={4}>
          {/* Panel de creación de nota */}
          <Card className="mb-4">
            <Card.Header>
              <h5 className="mb-0">Crear Nota</h5>
            </Card.Header>
            <Card.Body>
              <Form>
                <Form.Group className="mb-3">
                  <Form.Label>Título de la nota</Form.Label>
                  <Form.Control
                    type="text"
                    value={noteTitle}
                    onChange={(e) => setNoteTitle(e.target.value)}
                    placeholder="Ingrese un título para la nota"
                  />
                </Form.Group>
                
                <Form.Group className="mb-3">
                  <Form.Check 
                    type="checkbox"
                    id="is-whiteboard"
                    label="Es una pizarra (whiteboard)"
                    checked={isWhiteboard}
                    onChange={(e) => setIsWhiteboard(e.target.checked)}
                  />
                  <Form.Text className="text-muted">
                    Marque esta opción si la imagen es una pizarra o un dibujo a mano.
                  </Form.Text>
                </Form.Group>
                
                <Button
                  variant="primary"
                  className="w-100"
                  onClick={handleCreateNote}
                  disabled={creatingNote || !noteTitle.trim()}
                >
                  {creatingNote ? (
                    <>
                      <Spinner animation="border" size="sm" className="me-2" />
                      Creando...
                    </>
                  ) : (
                    <>
                      <i className="fas fa-save me-2"></i> Crear Nota
                    </>
                  )}
                </Button>
              </Form>
            </Card.Body>
          </Card>
          
          {/* Panel de miniatura */}
          {ocrResult?.thumbnail_url && (
            <Card className="mb-4">
              <Card.Header>
                <h5 className="mb-0">Archivo Original</h5>
              </Card.Header>
              <Card.Body className="text-center">
                <img 
                  src={ocrResult.thumbnail_url} 
                  alt="Miniatura del archivo original"
                  className="img-thumbnail ocr-thumbnail"
                />
                <p className="mt-2 mb-0 text-muted">
                  {ocrResult.filename}
                </p>
              </Card.Body>
            </Card>
          )}
          
          {/* Panel de estado de análisis */}
          {(textAnalysisLoading || topicsLoading) && (
            <Card className="mb-4 border-warning">
              <Card.Body className="d-flex align-items-center">
                <Spinner animation="border" size="sm" className="me-2" variant="warning" />
                <span>Analizando contenido...</span>
              </Card.Body>
            </Card>
          )}
          
          {/* Botón de volver */}
          <div className="d-grid gap-2">
            <Button 
              variant="outline-secondary"
              onClick={() => navigate('/upload')}
            >
              <i className="fas fa-arrow-left me-2"></i> Volver a cargar archivos
            </Button>
          </div>
        </Col>
      </Row>
    </Container>
  );
};

export default OcrPreviewPage;
