import apiClient from './client';

interface Note {
  id: number;
  title: string;
  content: string;
  created_at: string;
  updated_at: string;
  user_id: number;
  tags?: Tag[];
  topics?: Topic[];
}

interface Tag {
  id: number;
  name: string;
}

interface Topic {
  id: number;
  name: string;
}

interface CreateNoteData {
  title: string;
  content: string;
  tags?: string[]; // Nombres de etiquetas
  topics?: string[]; // Nombres de temas
}

interface UpdateNoteData {
  title?: string;
  content?: string;
  tags?: string[]; // Nombres de etiquetas
  topics?: string[]; // Nombres de temas
}

interface NotesFilters {
  search?: string;
  tag?: string;
  topic?: string;
  tags?: string[];
  topics?: string[];
  sort?: string;
  source_types?: string[];
  date?: string;
  date_from?: string;
  date_to?: string;
  page?: number;
  per_page?: number;
}

// Exportar las interfaces para que puedan ser importadas por otros módulos
export type { Note, Tag, Topic, NotesFilters, CreateNoteData, UpdateNoteData };

export const notesApi = {
  // Mantener getAllNotes para compatibilidad con código existente
  getAllNotes: async (filters?: NotesFilters) => {
    const response = await apiClient.get('/notes', { params: filters });
    return response.data;
  },
  
  // Nuevo método getNotes con el mismo comportamiento pero con nombre consistente
  getNotes: async (filters?: NotesFilters) => {
    const response = await apiClient.get('/notes', { params: filters });
    return response.data;
  },
  
  // Método para obtener temas
  getTopics: async () => {
    const response = await apiClient.get('/notes/topics');
    return response.data;
  },
  
  getNoteById: async (id: number) => {
    const response = await apiClient.get(`/notes/${id}`);
    return response.data;
  },
  
  createNote: async (noteData: CreateNoteData) => {
    const response = await apiClient.post('/notes', noteData);
    return response.data;
  },
  
  updateNote: async (id: number, noteData: UpdateNoteData) => {
    const response = await apiClient.put(`/notes/${id}`, noteData);
    return response.data;
  },
  
  deleteNote: async (id: number) => {
    const response = await apiClient.delete(`/notes/${id}`);
    return response.data;
  },

  getRecentNotes: async (limit: number = 5) => {
    const response = await apiClient.get('/notes/recent', { params: { limit } });
    return response.data;
  },
  
  getNotesStatistics: async () => {
    const response = await apiClient.get('/notes/statistics');
    return response.data;
  },

  searchNotes: async (query: string) => {
    const response = await apiClient.get('/notes/search', { params: { q: query } });
    return response.data;
  }
};
