import React, { useState, useEffect } from 'react';
import { Card, Button, Row, Col, Form, InputGroup } from 'react-bootstrap';
import './NotesFilterBar.css';

interface Topic {
  id: number;
  name: string;
}

interface Tag {
  id: number;
  name: string;
}

export interface NotesFilter {
  search?: string;
  topic?: string;
  tag?: string;
  source_types?: string[];
  date?: string;
  date_from?: string;
  date_to?: string;
  sort?: string;
  page?: number;
}

interface NotesFilterBarProps {
  initialFilters: NotesFilter;
  onFilterChange: (filters: NotesFilter) => void;
  topics: Topic[];
  tags: Tag[];
  isLoading?: boolean;
  onViewModeChange: (mode: 'grid' | 'list') => void;
  currentViewMode: 'grid' | 'list';
}

const NotesFilterBar: React.FC<NotesFilterBarProps> = ({
  initialFilters,
  onFilterChange,
  topics,
  tags,
  isLoading = false,
  onViewModeChange,
  currentViewMode
}) => {
  // Estado local para los filtros
  const [filters, setFilters] = useState<NotesFilter>(initialFilters);
  const [sourceTypes, setSourceTypes] = useState<string[]>(initialFilters.source_types || []);
  
  // Actualizar estado local cuando cambien los initialFilters
  useEffect(() => {
    setFilters(initialFilters);
    setSourceTypes(initialFilters.source_types || []);
  }, [initialFilters]);

  // Manejar cambios en los filtros básicos
  const handleFilterChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    
    const updatedFilters = {
      ...filters,
      [name]: value
    };
    
    // Si cambiamos el filtro de fecha y no es personalizado, eliminamos los campos date_from y date_to
    if (name === 'date' && value !== 'custom') {
      delete updatedFilters.date_from;
      delete updatedFilters.date_to;
    }
    
    setFilters(updatedFilters);
  };

  // Manejar cambios en los checkboxes de tipo de fuente
  const handleSourceTypeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { value, checked } = e.target;
    
    let updatedSourceTypes: string[];
    
    if (checked) {
      updatedSourceTypes = [...sourceTypes, value];
    } else {
      updatedSourceTypes = sourceTypes.filter(type => type !== value);
    }
    
    setSourceTypes(updatedSourceTypes);
    
    setFilters({
      ...filters,
      source_types: updatedSourceTypes.length > 0 ? updatedSourceTypes : undefined
    });
  };

  // Enviar el formulario de búsqueda
  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    
    // Preparar filtros finales
    const finalFilters: NotesFilter = {
      ...filters,
      // Reset to page 1 on new search
      page: 1
    };
    
    // Añadir source_types solo si hay alguno seleccionado
    if (sourceTypes && sourceTypes.length > 0) {
      finalFilters.source_types = sourceTypes;
    } else {
      delete finalFilters.source_types;
    }

    // Si la fecha no es personalizada, eliminamos los campos date_from y date_to
    if (filters.date !== 'custom') {
      delete finalFilters.date_from;
      delete finalFilters.date_to;
    }
    
    // Aplicar los filtros
    onFilterChange(finalFilters);
  };

  // Limpiar todos los filtros
  const handleClearFilters = () => {
    const clearedFilters: NotesFilter = {
      search: '',
      page: 1
    };
    setFilters(clearedFilters);
    setSourceTypes([]);
    onFilterChange(clearedFilters);
  };

  return (
    <Card className="mb-4" id="filter-container">
      <Card.Body>
        <Form id="search-form" onSubmit={handleSubmit}>
          <Row className="g-3 mb-3">
            {/* Búsqueda y botones de acción */}
            <Col md={6}>
              <InputGroup>
                <InputGroup.Text><i className="fas fa-search"></i></InputGroup.Text>
                <Form.Control
                  type="text"
                  id="search-input"
                  name="search"
                  placeholder="Buscar notas..."
                  value={filters.search || ''}
                  onChange={handleFilterChange}
                  aria-label="Buscar notas"
                />
                <Button type="submit" variant="primary" disabled={isLoading}>
                  {isLoading ? (
                    <>
                      <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                      <span>Buscando...</span>
                    </>
                  ) : (
                    <>Buscar</>
                  )}
                </Button>
              </InputGroup>
            </Col>
            
            {/* Filtros básicos */}
            <Col md={3}>
              <Form.Select 
                id="filter-topic"
                name="topic"
                value={filters.topic || ''}
                onChange={handleFilterChange}
                aria-label="Filtrar por tema"
              >
                <option value="">Todos los temas</option>
                {topics.map(topic => (
                  <option key={topic.id} value={topic.name}>
                    {topic.name}
                  </option>
                ))}
              </Form.Select>
            </Col>
            
            <Col md={3}>
              <Form.Select 
                id="filter-tag"
                name="tag"
                value={filters.tag || ''}
                onChange={handleFilterChange}
                aria-label="Filtrar por etiqueta"
              >
                <option value="">Todas las etiquetas</option>
                {tags.map(tag => (
                  <option key={tag.id} value={tag.name}>
                    {tag.name}
                  </option>
                ))}
              </Form.Select>
            </Col>
            
            {/* Fecha */}
            <Col md={4} className="mt-3">
              <Form.Label>Fecha</Form.Label>
              <Form.Select 
                id="filter-date"
                name="date"
                value={filters.date || ''}
                onChange={handleFilterChange}
                className="mb-2"
                aria-label="Filtrar por fecha"
              >
                <option value="">Cualquier fecha</option>
                <option value="today">Hoy</option>
                <option value="this_week">Esta semana</option>
                <option value="this_month">Este mes</option>
                <option value="custom">Personalizado</option>
              </Form.Select>
              
              {/* Rango de fechas personalizado */}
              {filters.date === 'custom' && (
                <Row id="date-range-container" className="mt-2">
                  <Col md={6}>
                    <Form.Label htmlFor="date-from">Desde</Form.Label>
                    <Form.Control
                      type="date" 
                      id="date-from"
                      name="date_from"
                      value={filters.date_from || ''}
                      onChange={handleFilterChange}
                      aria-label="Fecha desde"
                    />
                  </Col>
                  <Col md={6}>
                    <Form.Label htmlFor="date-to">Hasta</Form.Label>
                    <Form.Control
                      type="date" 
                      id="date-to"
                      name="date_to"
                      value={filters.date_to || ''}
                      onChange={handleFilterChange}
                      aria-label="Fecha hasta"
                    />
                  </Col>
                </Row>
              )}
            </Col>
            
            {/* Filtro por tipo de fuente */}
            <Col md={4} className="mt-3">
              <Form.Label>Tipo de fuente</Form.Label>
              <div>
                <Form.Check
                  inline
                  type="checkbox" 
                  id="source-text" 
                  label="Texto"
                  value="Texto"
                  checked={sourceTypes.includes('Texto')}
                  onChange={handleSourceTypeChange}
                />
                <Form.Check
                  inline
                  type="checkbox" 
                  id="source-ocr" 
                  label="OCR"
                  value="OCR"
                  checked={sourceTypes.includes('OCR')}
                  onChange={handleSourceTypeChange}
                />
                <Form.Check
                  inline
                  type="checkbox" 
                  id="source-pdf" 
                  label="PDF"
                  value="PDF"
                  checked={sourceTypes.includes('PDF')}
                  onChange={handleSourceTypeChange}
                />
              </div>
            </Col>
            
            {/* Ordenación */}
            <Col md={4} className="mt-3">
              <Form.Label htmlFor="sort-by">Ordenar por</Form.Label>
              <Form.Select 
                id="sort-by"
                name="sort"
                value={filters.sort || ''}
                onChange={handleFilterChange}
                aria-label="Ordenar notas"
              >
                <option value="date_desc">Más recientes primero</option>
                <option value="date_asc">Más antiguos primero</option>
                <option value="title_asc">Título A-Z</option>
                <option value="title_desc">Título Z-A</option>
                <option value="relevance">Relevancia</option>
              </Form.Select>
            </Col>
            
            {/* Botones de acción */}
            <Col md={12} className="d-flex justify-content-between align-items-center mt-4">
              <Button 
                variant="outline-secondary" 
                type="button" 
                onClick={handleClearFilters}
                aria-label="Limpiar filtros"
              >
                <i className="fas fa-times me-2"></i>Limpiar filtros
              </Button>
              
              <div className="btn-group" role="group" aria-label="Modo de vista">
                <Button 
                  type="button" 
                  variant={currentViewMode === 'grid' ? 'primary' : 'outline-primary'}
                  onClick={() => onViewModeChange('grid')}
                  aria-pressed={currentViewMode === 'grid'}
                  id="grid-view-btn"
                >
                  <i className="fas fa-th-large me-2"></i>
                  <span className="d-none d-sm-inline">Cuadrícula</span>
                </Button>
                <Button 
                  type="button" 
                  variant={currentViewMode === 'list' ? 'primary' : 'outline-primary'}
                  onClick={() => onViewModeChange('list')}
                  aria-pressed={currentViewMode === 'list'}
                  id="list-view-btn"
                >
                  <i className="fas fa-list me-2"></i>
                  <span className="d-none d-sm-inline">Lista</span>
                </Button>
              </div>
            </Col>
          </Row>
        </Form>
      </Card.Body>
    </Card>
  );
};

export default NotesFilterBar;
