import apiClient from './client';

interface LoginCredentials {
  username: string;
  password: string;
}

interface RegisterData {
  username: string;
  email: string;
  name: string;
  password: string;
}

interface SecurityQuestionData {
  question: string;
  answer: string;
}

interface PasswordResetData {
  username: string;
  answer: string;
  new_password: string;
}

export const authApi = {
  login: async (credentials: LoginCredentials) => {
    // El backend espera /api/auth/login, pero baseURL ya incluye /api
    // por lo que la ruta correcta es solo /auth/login
    const response = await apiClient.post('/auth/login', credentials);
    return response.data;
  },
  
  register: async (userData: RegisterData) => {
    const response = await apiClient.post('/auth/register', userData);
    return response.data;
  },
  
  logout: async () => {
    const response = await apiClient.post('/auth/logout');
    return response.data;
  },
  
  getSecurityQuestion: async (username: string) => {
    const response = await apiClient.get(`/auth/get-security-question?username=${username}`);
    return response.data;
  },
  
  setSecurityQuestion: async (data: SecurityQuestionData) => {
    const response = await apiClient.post('/auth/security-question', data);
    return response.data;
  },
  
  resetPasswordWithAnswer: async (data: PasswordResetData) => {
    const response = await apiClient.post('/auth/reset-password-with-answer', data);
    return response.data;
  },
  
  changePassword: async (currentPassword: string, newPassword: string) => {
    const response = await apiClient.post('/auth/change-password', {
      current_password: currentPassword,
      new_password: newPassword,
    });
    return response.data;
  },
  
  getUserProfile: async () => {
    const response = await apiClient.get('/auth/user');
    return response.data;
  },
};
