import React, { useState, useEffect, useRef } from 'react';
import { Card, Badge, Button, InputGroup, Form } from 'react-bootstrap';
import './TagsManager.css';

interface Tag {
  id?: number;
  name: string;
}

interface TagsManagerProps {
  tags: Tag[];
  availableTags?: Tag[];
  onSaveTags?: (tags: Tag[]) => void;
  onCreateTag?: (tagName: string) => Promise<Tag>;
}

const TagsManager: React.FC<TagsManagerProps> = ({ 
  tags = [], 
  availableTags = [],
  onSaveTags,
  onCreateTag
}) => {
  const [showPanel, setShowPanel] = useState<boolean>(true);
  const [isEditMode, setIsEditMode] = useState<boolean>(false);
  const [tagInput, setTagInput] = useState<string>('');
  const [filteredTags, setFilteredTags] = useState<Tag[]>([]);
  const [currentTags, setCurrentTags] = useState<Tag[]>(tags);
  const tagInputRef = useRef<HTMLInputElement>(null);

  // Filtrar etiquetas disponibles en función del input
  useEffect(() => {
    if (tagInput.trim()) {
      const filtered = availableTags.filter(
        tag => tag.name.toLowerCase().includes(tagInput.toLowerCase())
      ).filter(
        // Filtrar las que ya están seleccionadas
        tag => !currentTags.some(t => t.name === tag.name)
      );
      setFilteredTags(filtered);
    } else {
      setFilteredTags([]);
    }
  }, [tagInput, availableTags, currentTags]);

  // Manejar entrada en modo edición
  const handleEnterEditMode = () => {
    setIsEditMode(true);
    setTagInput('');
    setCurrentTags([...tags]);
    // Focus en el input una vez que esté renderizado
    setTimeout(() => {
      if (tagInputRef.current) {
        tagInputRef.current.focus();
      }
    }, 50);
  };

  // Cancelar edición
  const handleCancelEdit = () => {
    setIsEditMode(false);
    setTagInput('');
    setCurrentTags([...tags]);
  };

  // Guardar cambios en etiquetas
  const handleSaveTags = () => {
    if (onSaveTags) {
      onSaveTags(currentTags);
    }
    setIsEditMode(false);
    setTagInput('');
  };

  // Añadir etiqueta desde el input
  const handleAddTag = async () => {
    if (!tagInput.trim()) return;
    
    // Verificar si la etiqueta ya existe
    const existingTag = availableTags.find(
      tag => tag.name.toLowerCase() === tagInput.toLowerCase()
    );
    
    if (existingTag) {
      if (!currentTags.some(t => t.name === existingTag.name)) {
        setCurrentTags([...currentTags, existingTag]);
      }
    } else if (onCreateTag) {
      try {
        // Crear nueva etiqueta a través de la API
        const newTag = await onCreateTag(tagInput.trim());
        setCurrentTags([...currentTags, newTag]);
      } catch (error) {
        console.error('Error al crear etiqueta:', error);
      }
    } else {
      // Crear etiqueta localmente (sin API)
      const newTag: Tag = {
        id: Math.floor(Math.random() * -1000), // ID temporal negativo
        name: tagInput.trim()
      };
      setCurrentTags([...currentTags, newTag]);
    }
    
    setTagInput('');
    if (tagInputRef.current) {
      tagInputRef.current.focus();
    }
  };

  // Añadir etiqueta desde la lista de sugerencias
  const handleAddSuggestion = (tag: Tag) => {
    if (!currentTags.some(t => t.name === tag.name)) {
      setCurrentTags([...currentTags, tag]);
      setTagInput('');
      if (tagInputRef.current) {
        tagInputRef.current.focus();
      }
    }
  };

  // Eliminar etiqueta
  const handleRemoveTag = (index: number) => {
    const newTags = [...currentTags];
    newTags.splice(index, 1);
    setCurrentTags(newTags);
  };

  // Manejar teclas especiales
  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      handleAddTag();
    } else if (e.key === 'Escape') {
      setTagInput('');
      setFilteredTags([]);
    }
  };

  return (
    <Card className="mb-4">
      <Card.Header className="d-flex justify-content-between align-items-center">
        <h5 className="mb-0">Etiquetas</h5>
        <div>
          {!isEditMode ? (
            <Button 
              size="sm" 
              variant="outline-secondary" 
              className="me-2"
              title="Gestionar etiquetas"
              onClick={handleEnterEditMode}
            >
              <i className="fas fa-edit"></i>
            </Button>
          ) : null}
          <Button 
            variant="link" 
            className="p-0 border-0 card-toggle" 
            onClick={() => setShowPanel(!showPanel)}
            aria-expanded={showPanel}
          >
            <i className={`fas fa-chevron-${showPanel ? 'up' : 'down'}`}></i>
          </Button>
        </div>
      </Card.Header>
      
      {showPanel && (
        <Card.Body>
          {!isEditMode ? (
            // Modo vista
            <div className="tags-container">
              {currentTags.length > 0 ? (
                currentTags.map((tag, index) => (
                  <Badge 
                    bg="secondary" 
                    className="me-1 mb-1" 
                    key={tag.id || index}
                  >
                    {tag.name}
                  </Badge>
                ))
              ) : (
                <span className="text-muted">No hay etiquetas asignadas</span>
              )}
            </div>
          ) : (
            // Modo edición
            <>
              <div className="selected-tags mb-3">
                {currentTags.map((tag, index) => (
                  <Badge 
                    bg="secondary" 
                    className="me-1 mb-1 tag-badge" 
                    key={tag.id || index}
                  >
                    {tag.name}
                    <span 
                      className="tag-remove-btn ms-1" 
                      onClick={() => handleRemoveTag(index)}
                    >
                      ×
                    </span>
                  </Badge>
                ))}
                {currentTags.length === 0 && (
                  <div className="text-muted small">No hay etiquetas seleccionadas</div>
                )}
              </div>
              
              <div className="position-relative">
                <InputGroup>
                  <Form.Control
                    ref={tagInputRef}
                    placeholder="Escribe para añadir una etiqueta..."
                    value={tagInput}
                    onChange={(e) => setTagInput(e.target.value)}
                    onKeyDown={handleKeyDown}
                  />
                  <Button 
                    variant="outline-secondary"
                    onClick={handleAddTag}
                  >
                    <i className="fas fa-plus"></i>
                  </Button>
                </InputGroup>
                
                {filteredTags.length > 0 && (
                  <div className="tags-dropdown">
                    {filteredTags.map((tag) => (
                      <div 
                        className="tag-item" 
                        key={tag.id}
                        onClick={() => handleAddSuggestion(tag)}
                      >
                        {tag.name}
                      </div>
                    ))}
                  </div>
                )}
              </div>
                            
              <div className="d-flex justify-content-end mt-3">
                <Button 
                  variant="outline-secondary" 
                  size="sm" 
                  className="me-2"
                  onClick={handleCancelEdit}
                >
                  <i className="fas fa-times"></i> Cancelar
                </Button>
                <Button 
                  variant="primary" 
                  size="sm"
                  onClick={handleSaveTags}
                >
                  <i className="fas fa-save"></i> Guardar etiquetas
                </Button>
              </div>
            </>
          )}
        </Card.Body>
      )}
    </Card>
  );
};

export default TagsManager;
