import React, { useState, useEffect } from 'react';
import { useSearchParams } from 'react-router-dom';
import { notesApi } from '../../../api/notes';
import { tagsApi } from '../../../api/tags';
import type { Tag as ApiTag } from '../../../api/tags';
import NoteCard from '../components/NoteCard';
import type { NoteCardProps } from '../components/NoteCard';
import NotesFilterBar from '../components/NotesFilterBar';
import type { NotesFilter } from '../components/NotesFilterBar';
import Pagination from '../components/Pagination';
import './NotesListPage.css';

interface Topic {
  id: number;
  name: string;
}

interface PaginatedNotesResponse {
  items: NoteCardProps[];
  total: number;
  page: number;
  pages: number;
}

const NotesListPage: React.FC = () => {
  // Estado para las notas y metadatos relacionados
  const [notes, setNotes] = useState<NoteCardProps[]>([]);
  const [topics, setTopics] = useState<Topic[]>([]);
  const [tags, setTags] = useState<ApiTag[]>([]);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [totalNotes, setTotalNotes] = useState(0);
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Usar URLSearchParams para manejar filtros desde la URL
  const [searchParams, setSearchParams] = useSearchParams();

  // Extraer filtros de los parámetros de la URL
  const getFiltersFromUrl = (): NotesFilter => {
    const filters: NotesFilter = {};
    
    if (searchParams.has('search')) filters.search = searchParams.get('search') || undefined;
    if (searchParams.has('topic')) filters.topic = searchParams.get('topic') || undefined;
    if (searchParams.has('tag')) filters.tag = searchParams.get('tag') || undefined;
    if (searchParams.has('sort')) filters.sort = searchParams.get('sort') || undefined;
    if (searchParams.has('page')) filters.page = parseInt(searchParams.get('page') || '1');
    if (searchParams.has('date')) filters.date = searchParams.get('date') || undefined;
    
    // Solo incluir date_from y date_to si date es 'custom'
    if (filters.date === 'custom') {
      if (searchParams.has('date_from')) filters.date_from = searchParams.get('date_from') || undefined;
      if (searchParams.has('date_to')) filters.date_to = searchParams.get('date_to') || undefined;
    }
    
    // Manejar source_types como array
    if (searchParams.has('source_types')) {
      const sourceTypes = searchParams.get('source_types');
      if (sourceTypes) {
        filters.source_types = sourceTypes.split(',');
      }
    }
    
    return filters;
  };

  // Cargar preferencia de vista guardada
  useEffect(() => {
    const savedViewMode = localStorage.getItem('notesViewMode');
    if (savedViewMode === 'list' || savedViewMode === 'grid') {
      setViewMode(savedViewMode);
    }
  }, []);

  // Cargar temas y etiquetas para los filtros
  useEffect(() => {
    const fetchTopicsAndTags = async () => {
      try {
        const [topicsResponse, tagsResponse] = await Promise.all([
          notesApi.getTopics(),
          tagsApi.getTags()
        ]);
        
        setTopics(topicsResponse.items || []);
        setTags(tagsResponse.items || []);
      } catch (error) {
        console.error('Error al cargar temas y etiquetas:', error);
        setError('Error al cargar filtros. Inténtalo de nuevo más tarde.');
      }
    };
    
    fetchTopicsAndTags();
  }, []);

  // Cargar notas cuando cambien los filtros o la página
  useEffect(() => {
    const fetchNotes = async () => {
      setIsLoading(true);
      setError(null);
      
      try {
        const filters = getFiltersFromUrl();
        
        // Asegurar que siempre haya un número de página
        const page = filters.page || 1;
        
        const response: PaginatedNotesResponse = await notesApi.getNotes({
          ...filters,
          page
        });
        
        setNotes(response.items || []);
        setCurrentPage(response.page || 1);
        setTotalPages(response.pages || 1);
        setTotalNotes(response.total || 0);
      } catch (error) {
        console.error('Error al cargar notas:', error);
        setError('Error al cargar las notas. Inténtalo de nuevo más tarde.');
      } finally {
        setIsLoading(false);
      }
    };
    
    fetchNotes();
  }, [searchParams]);

  // Manejar cambios en los filtros
  const handleFilterChange = (filters: NotesFilter) => {
    // Crear nuevo objeto URLSearchParams
    const newParams = new URLSearchParams();
    
    // Añadir solo los filtros con valor
    if (filters.search) newParams.set('search', filters.search);
    if (filters.topic) newParams.set('topic', filters.topic);
    if (filters.tag) newParams.set('tag', filters.tag);
    if (filters.sort) newParams.set('sort', filters.sort);
    if (filters.date) newParams.set('date', filters.date);
    
    // Solo añadir date_from y date_to si date es 'custom'
    if (filters.date === 'custom') {
      if (filters.date_from) newParams.set('date_from', filters.date_from);
      if (filters.date_to) newParams.set('date_to', filters.date_to);
    }
    
    // Añadir source_types como string separado por comas
    if (filters.source_types && filters.source_types.length > 0) {
      newParams.set('source_types', filters.source_types.join(','));
    }
    
    // Añadir página si es distinta de 1
    if (filters.page && filters.page > 1) {
      newParams.set('page', filters.page.toString());
    }
    
    // Actualizar la URL con los nuevos parámetros
    setSearchParams(newParams);
  };

  // Manejar cambio de página
  const handlePageChange = (newPage: number) => {
    const currentFilters = getFiltersFromUrl();
    handleFilterChange({
      ...currentFilters,
      page: newPage
    });
  };

  // Manejar cambio de modo de vista
  const handleViewModeChange = (mode: 'grid' | 'list') => {
    setViewMode(mode);
    localStorage.setItem('notesViewMode', mode);
  };

  // Manejar eliminación de una nota
  const handleDeleteNote = async (noteId: number) => {
    try {
      await notesApi.deleteNote(noteId);
      
      // Actualizar el estado local para eliminar la nota sin recargar
      setNotes(notes.filter(note => note.id !== noteId));
      
      // Si era la última nota de la página y no es la primera página, ir a la página anterior
      if (notes.length === 1 && currentPage > 1) {
        handlePageChange(currentPage - 1);
      } else {
        // Recargar la página actual para actualizar el conteo total
        const currentFilters = getFiltersFromUrl();
        handleFilterChange({
          ...currentFilters,
          page: currentPage
        });
      }
    } catch (error) {
      console.error('Error al eliminar nota:', error);
      setError('Error al eliminar la nota. Inténtalo de nuevo más tarde.');
    }
  };

  return (
    <div className="container-fluid py-4">
      <div className="d-flex justify-content-between align-items-center mb-4">
        <h1>Mis Notas</h1>
        <a href="/notes/new" className="btn btn-primary">
          <i className="fas fa-plus-circle me-2"></i>Nueva Nota
        </a>
      </div>
      
      {/* Barra de filtros */}
      <NotesFilterBar
        initialFilters={getFiltersFromUrl()}
        onFilterChange={handleFilterChange}
        topics={topics}
        tags={tags}
        isLoading={isLoading}
        onViewModeChange={handleViewModeChange}
        currentViewMode={viewMode}
      />
      
      {/* Mensajes de estado */}
      {error && (
        <div className="alert alert-danger" role="alert">
          <i className="fas fa-exclamation-circle me-2"></i>
          {error}
        </div>
      )}
      
      {/* Mostrar cantidad de resultados */}
      {!isLoading && !error && (
        <div className="d-flex justify-content-between align-items-center mb-3">
          <div>
            <p className="text-muted mb-0">
              {totalNotes === 0 ? (
                'No se encontraron notas'
              ) : totalNotes === 1 ? (
                '1 nota encontrada'
              ) : (
                `${totalNotes} notas encontradas`
              )}
              {searchParams.toString() && ' con los filtros aplicados'}
            </p>
          </div>
        </div>
      )}
      
      {/* Contenedor de notas con modo de vista */}
      <div id="notes-container" className={viewMode === 'list' ? 'list-view' : 'grid-view'}>
        {isLoading ? (
          <div className="text-center py-5">
            <div className="spinner-border text-primary" role="status">
              <span className="visually-hidden">Cargando...</span>
            </div>
            <p className="mt-2">Cargando notas...</p>
          </div>
        ) : notes.length === 0 ? (
          <div className="text-center py-5">
            <i className="fas fa-sticky-note fa-4x text-muted mb-3"></i>
            <h4>No hay notas disponibles</h4>
            <p className="text-muted">
              {searchParams.toString() 
                ? 'Prueba a cambiar los filtros o crear una nueva nota.'
                : 'Comienza creando una nueva nota.'}
            </p>
            <a href="/notes/new" className="btn btn-primary mt-2">
              <i className="fas fa-plus-circle me-2"></i>Crear nota
            </a>
          </div>
        ) : (
          <div className="row">
            {notes.map(note => (
              <div 
                className={viewMode === 'grid' ? 'col-md-6 col-lg-4 mb-4' : 'col-12 mb-3'} 
                key={note.id}
              >
                <NoteCard 
                  note={note}
                  viewMode={viewMode}
                  onDelete={handleDeleteNote}
                />
              </div>
            ))}
          </div>
        )}
      </div>
      
      {/* Paginación */}
      <Pagination
        currentPage={currentPage}
        totalPages={totalPages}
        onPageChange={handlePageChange}
        isLoading={isLoading}
      />
    </div>
  );
};

export default NotesListPage;
