import React, { useState, useEffect } from 'react';
import { Card, Badge, Button, ProgressBar, Form, Spinner } from 'react-bootstrap';
import { analysisApi } from '../../../api/analysis';
import type { TopicDistribution } from '../../../api/analysis';
import './TopicsPanel.css';

interface Topic {
  id: number;
  name: string;
  confidence?: number;
}

interface TopicsPanelProps {
  mainTopic?: string;
  topics?: Array<Topic>;
  suggestedTopics?: Array<string>;
  topicsDistribution?: Array<TopicDistribution>;
  confidence?: number;
  availableTopics?: Array<Topic>;
  onSaveTopics?: (mainTopic: string, topics: Array<Topic>) => void;
  noteId?: number;
  content?: string;
}

const TopicsPanel: React.FC<TopicsPanelProps> = ({ 
  mainTopic = '', 
  topics = [], 
  suggestedTopics = [],
  topicsDistribution = [],
  confidence = 0,
  availableTopics = [],
  onSaveTopics,
  noteId,
  content = ''
}) => {
  const [showPanel, setShowPanel] = useState<boolean>(true);
  const [isEditing, setIsEditing] = useState<boolean>(false);
  const [editMainTopic, setEditMainTopic] = useState<string>(mainTopic);
  const [editTopics, setEditTopics] = useState<Topic[]>(topics);
  const [selectedTopic, setSelectedTopic] = useState<string>('');
  
  // Estado para análisis de temas
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [localTopicsDistribution, setLocalTopicsDistribution] = useState<TopicDistribution[]>(topicsDistribution);
  const [localSuggestedTopics, setLocalSuggestedTopics] = useState<string[]>(suggestedTopics);
  const [localConfidence, setLocalConfidence] = useState<number>(confidence);
  const [localMainTopic, setLocalMainTopic] = useState<string>(mainTopic);
  
  // Analizar temas cuando cambia el contenido
  useEffect(() => {
    if (content && content.trim().length > 50) {
      analyzeTopics(content);
    }
  }, [content, noteId]);
  
  // Función para analizar temas
  const analyzeTopics = async (textContent: string) => {
    // No analizamos si estamos en modo edición
    if (isEditing) return;
    
    setLoading(true);
    setError(null);
    
    try {
      const result = await analysisApi.analyzeTopics(textContent, noteId);
      
      setLocalTopicsDistribution(result.topics_distribution);
      setLocalSuggestedTopics(result.suggested_topics);
      setLocalConfidence(result.main_topic_confidence * 100); // Convertir a porcentaje
      setLocalMainTopic(result.main_topic);
      
      // Solo actualizar con nuevos valores si no estamos en modo edición
      if (!isEditing && onSaveTopics && result.main_topic) {
        // Crear estructura de temas basada en la distribución
        // Nota: guardamos el análisis en las variables locales, pero no llamamos
        // a onSaveTopics aquí para evitar loops - el componente padre debe manejar la persistencia
        // cuando decide que es apropiado (por ejemplo, al guardar explícitamente)
        
        // El código siguiente está comentado para evitar llamadas automáticas que puedan generar loops
        /*
        const newTopics = result.topics_distribution
          .filter(item => item.topic !== result.main_topic && item.percentage > 0.05) // Solo temas con más de 5% de relevancia
          .map(item => {
            const existingTopic = availableTopics.find(t => t.name === item.topic);
            return existingTopic || {
              id: Math.floor(Math.random() * -1000), // ID temporal negativo
              name: item.topic
            };
          });
        
        onSaveTopics(result.main_topic, newTopics);
        */
      }
    } catch (err) {
      console.error('Error al analizar temas:', err);
      setError('Error al analizar temas');
    } finally {
      setLoading(false);
    }
  };

  // Manejar modo de edición
  const handleEditMode = () => {
    setIsEditing(true);
    setEditMainTopic(mainTopic);
    setEditTopics([...topics]);
  };

  // Cancelar edición
  const handleCancelEdit = () => {
    setIsEditing(false);
    setEditMainTopic(mainTopic);
    setEditTopics([...topics]);
  };

  // Guardar cambios en temas
  const handleSaveTopics = () => {
    if (onSaveTopics) {
      onSaveTopics(editMainTopic, editTopics);
    }
    setIsEditing(false);
  };

  // Añadir tema seleccionado
  const handleAddTopic = () => {
    if (selectedTopic && !editTopics.some(t => t.name === selectedTopic)) {
      const topic = availableTopics.find(t => t.name === selectedTopic);
      if (topic) {
        setEditTopics([...editTopics, topic]);
      } else if (selectedTopic.trim()) {
        // Si el tema no existe en los disponibles, crear uno nuevo
        const newTopic = {
          id: Math.floor(Math.random() * -1000), // ID temporal negativo
          name: selectedTopic.trim()
        };
        setEditTopics([...editTopics, newTopic]);
      }
      setSelectedTopic('');
    }
  };

  // Eliminar tema
  const handleRemoveTopic = (topicId: number) => {
    setEditTopics(editTopics.filter(t => t.id !== topicId));
  };

  // Añadir tema sugerido
  const handleAddSuggested = (topicName: string) => {
    if (!editTopics.some(t => t.name === topicName)) {
      const topic = availableTopics.find(t => t.name === topicName);
      if (topic) {
        setEditTopics([...editTopics, topic]);
      } else if (topicName.trim()) {
        const newTopic = {
          id: Math.floor(Math.random() * -1000), // ID temporal negativo
          name: topicName.trim()
        };
        setEditTopics([...editTopics, newTopic]);
      }
    }
  };

  return (
    <Card className="mb-4">
      <Card.Header className="d-flex justify-content-between align-items-center">
        <h5 className="mb-0">Clasificación</h5>
        <div>
          {!isEditing ? (
            <Button 
              size="sm" 
              variant="outline-secondary" 
              className="me-2"
              title="Editar clasificación"
              onClick={handleEditMode}
            >
              <i className="fas fa-edit"></i>
            </Button>
          ) : null}
          <Button 
            variant="link" 
            className="p-0 border-0 card-toggle" 
            onClick={() => setShowPanel(!showPanel)}
            aria-expanded={showPanel}
          >
            <i className={`fas fa-chevron-${showPanel ? 'up' : 'down'}`}></i>
          </Button>
        </div>
      </Card.Header>
      
      {showPanel && (
        <Card.Body>
          {/* Modo vista normal */}
          {!isEditing ? (
            <>
              {/* Tema principal con visualización de confianza */}
              <div className="mb-3">
                <h6><i className="fas fa-bookmark"></i> Tema principal</h6>
                {loading ? (
                  <div className="d-flex align-items-center justify-content-center py-3">
                    <Spinner animation="border" size="sm" className="me-2" />
                    <span>Analizando temas...</span>
                  </div>
                ) : error ? (
                  <div className="text-danger small">{error}</div>
                ) : localMainTopic ? (
                  <div className="d-flex align-items-center mt-2">
                    <div className="flex-grow-1 me-2">
                      <Badge bg="primary" className="main-topic-badge">{localMainTopic}</Badge>
                    </div>
                    {localConfidence > 0 && (
                      <div className="confidence-meter" style={{ width: '100px' }}>
                        <small className="text-muted d-block">Confianza:</small>
                        <ProgressBar 
                          now={localConfidence} 
                          variant={localConfidence > 75 ? 'success' : localConfidence > 50 ? 'info' : 'warning'}
                          style={{ height: '8px' }}
                        />
                        <small className="d-block text-end">{localConfidence.toFixed(0)}%</small>
                      </div>
                    )}
                  </div>
                ) : (
                  <div className="text-muted">No hay tema principal asignado</div>
                )}
              </div>
              
              {/* Distribución de temas visualizada */}
              {localTopicsDistribution.length > 0 && (
                <div className="mb-3">
                  <h6><i className="fas fa-chart-pie"></i> Distribución de temas</h6>
                  <div className="topics-distribution mt-2">
                    {localTopicsDistribution.map((item, index) => (
                      <div key={index} className="topic-distribution-item mb-2">
                        <div className="d-flex justify-content-between mb-1">
                          <small>{item.topic}</small>
                          <small>{item.percentage}%</small>
                        </div>
                        <ProgressBar 
                          now={item.percentage} 
                          variant={index === 0 ? 'primary' : 'info'} 
                          style={{ height: '6px' }}
                        />
                      </div>
                    ))}
                  </div>
                </div>
              )}
              
              {/* Temas relacionados */}
              {topics.length > 0 && (
                <div className="mt-3">
                  <h6><i className="fas fa-tags"></i> Temas relacionados</h6>
                  <div className="d-flex flex-wrap gap-1 mt-2">
                    {topics.map((topic) => (
                      <Badge bg="secondary" className="me-1 mb-1" key={topic.id}>
                        {topic.name}
                      </Badge>
                    ))}
                  </div>
                </div>
              )}
              
              {/* Temas sugeridos */}
              {localSuggestedTopics.length > 0 && (
                <div className="mt-3" id="suggested-topics-container">
                  <h6><i className="fas fa-lightbulb"></i> Sugerencias</h6>
                  <div className="d-flex flex-wrap gap-1 mt-2">
                    {localSuggestedTopics.map((topic, index) => (
                      <Badge bg="light" text="dark" className="me-1 mb-1" key={index}>
                        {topic}
                      </Badge>
                    ))}
                  </div>
                </div>
              )}
            </>
          ) : (
            /* Modo edición */
            <>
              <div className="mb-3">
                <Form.Label htmlFor="edit-main-topic">Tema principal</Form.Label>
                <Form.Select 
                  id="edit-main-topic" 
                  value={editMainTopic}
                  onChange={(e) => setEditMainTopic(e.target.value)}
                >
                  <option value="">Sin tema principal</option>
                  {availableTopics.map((topic) => (
                    <option key={topic.id} value={topic.name}>
                      {topic.name}
                    </option>
                  ))}
                </Form.Select>
              </div>
              
              <div className="mb-3">
                <Form.Label>Temas relacionados</Form.Label>
                <div className="selected-topics mb-2">
                  {editTopics.map((topic) => (
                    <Badge 
                      bg="primary" 
                      className="me-1 mb-1 topic-badge"
                      key={topic.id}
                    >
                      {topic.name}
                      <span 
                        className="topic-remove-btn ms-1" 
                        onClick={() => handleRemoveTopic(topic.id)}
                      >
                        ×
                      </span>
                    </Badge>
                  ))}
                  {editTopics.length === 0 && (
                    <div className="text-muted small">Sin temas seleccionados</div>
                  )}
                </div>
                
                <div className="input-group mt-2">
                  <Form.Select
                    value={selectedTopic}
                    onChange={(e) => setSelectedTopic(e.target.value)}
                  >
                    <option value="">Seleccionar tema...</option>
                    {availableTopics
                      .filter(t => !editTopics.some(et => et.id === t.id))
                      .map((topic) => (
                        <option key={topic.id} value={topic.name}>
                          {topic.name}
                        </option>
                      ))}
                  </Form.Select>
                  <Button 
                    variant="outline-secondary"
                    onClick={handleAddTopic}
                  >
                    <i className="fas fa-plus"></i>
                  </Button>
                </div>
              </div>
              
              {/* Temas sugeridos (mode edición) */}
              {suggestedTopics.length > 0 && (
                <div className="mt-3 mb-3">
                  <h6><i className="fas fa-lightbulb"></i> Sugerencias</h6>
                  <div className="d-flex flex-wrap gap-1 mt-2">
                    {suggestedTopics
                      .filter(topic => !editTopics.some(t => t.name === topic))
                      .map((topic, index) => (
                        <Badge 
                          bg="light" 
                          text="dark" 
                          className="me-1 mb-1 topic-badge" 
                          key={index}
                          style={{ cursor: 'pointer' }}
                          onClick={() => handleAddSuggested(topic)}
                        >
                          {topic} <span className="ms-1 text-primary">+</span>
                        </Badge>
                      ))}
                  </div>
                </div>
              )}

              <div className="d-flex justify-content-end mt-3">
                <Button 
                  variant="outline-secondary" 
                  size="sm" 
                  className="me-2"
                  onClick={handleCancelEdit}
                >
                  <i className="fas fa-times"></i> Cancelar
                </Button>
                <Button 
                  variant="primary" 
                  size="sm"
                  onClick={handleSaveTopics}
                >
                  <i className="fas fa-save"></i> Guardar clasificación
                </Button>
              </div>
            </>
          )}
        </Card.Body>
      )}
    </Card>
  );
};

export default TopicsPanel;
