import React from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import rehypeRaw from 'rehype-raw';
import './NoteContent.css';

interface NoteContentProps {
  note: {
    title: string;
    content: string;
    created_at: string;
    updated_at?: string;
    source_type?: string;
  };
}

const NoteContent: React.FC<NoteContentProps> = ({ note }) => {
  // Formatear fecha
  const formatDate = (dateString: string) => {
    try {
      return new Date(dateString).toLocaleDateString('es-ES', {
        year: 'numeric',
        month: 'long',
        day: 'numeric'
      });
    } catch (e) {
      return 'Fecha desconocida';
    }
  };

  return (
    <div className="note-content-view">
      <h1 className="mb-4">{note.title || 'Sin título'}</h1>
      
      <div className="note-metadata mb-4">
        <span className="note-date me-3">
          <i className="fas fa-calendar-alt me-1"></i> {formatDate(note.created_at)}
        </span>
        
        {note.updated_at && note.updated_at !== note.created_at && (
          <span className="note-updated me-3">
            <i className="fas fa-edit me-1"></i> Actualizada: {formatDate(note.updated_at)}
          </span>
        )}
        
        {note.source_type && (
          <span className="note-source">
            <i className="fas fa-file-alt me-1"></i> {note.source_type}
          </span>
        )}
      </div>
      
      <div className="note-body">
        {note.content ? (
          <ReactMarkdown 
            remarkPlugins={[remarkGfm]} 
            rehypePlugins={[rehypeRaw]}
            components={{
              // Sobrescribir el componente div para aplicar nuestra clase personalizada
              div: ({node, ...props}) => <div className="markdown-content" {...props} />
            }}
          >
            {note.content}
          </ReactMarkdown>
        ) : (
          <p className="text-muted">No hay contenido disponible</p>
        )}
      </div>
    </div>
  );
};

export default NoteContent;
