import React, { useState } from 'react';
import './GraphLegend.css';

interface GraphLegendProps {
  nodeColors: Record<string, string>;
}

const GraphLegend: React.FC<GraphLegendProps> = ({ nodeColors }) => {
  const [collapsed, setCollapsed] = useState(false);

  // Obtener nombres legibles para los tipos de nodos
  const getTypeName = (type: string): string => {
    switch (type) {
      case 'concept': return 'Concepto';
      case 'topic': return 'Tema';
      case 'note': return 'Nota';
      case 'tag': return 'Etiqueta';
      case 'default': return 'Otros';
      default: return type.charAt(0).toUpperCase() + type.slice(1);
    }
  };

  return (
    <div className={`graph-legend ${collapsed ? 'collapsed' : ''}`}>
      <div className="legend-header" onClick={() => setCollapsed(!collapsed)}>
        <h6 className="mb-0">
          <i className="fas fa-info-circle me-2"></i>
          Leyenda
        </h6>
        <button className="btn btn-sm">
          {collapsed ? <i className="fas fa-chevron-down"></i> : <i className="fas fa-chevron-up"></i>}
        </button>
      </div>
      
      {!collapsed && (
        <div className="legend-body">
          <div className="legend-list">
            {Object.entries(nodeColors).map(([type, color]) => (
              <div key={type} className="legend-item">
                <span className="color-dot" style={{ backgroundColor: color }}></span>
                <span className="type-name">{getTypeName(type)}</span>
              </div>
            ))}
          </div>
          <div className="legend-footer">
            <small className="text-muted">
              Haz clic en un nodo para ver más información.
            </small>
          </div>
        </div>
      )}
    </div>
  );
};

export default GraphLegend;
