import React, { useCallback, useEffect, useRef, useState } from 'react';
import { ForceGraph2D } from 'react-force-graph';
import { graphApi } from '../../../api/graph';
import { NodeInfoPanel, GraphSearch, GraphLegend } from '../components';
// Importar tipos compartidos
import type { GraphNode, GraphEdge, GraphData } from '../types/graph.types';

// Tipo simple para el método ref del ForceGraph2D para evitar errores de tipado
// Usamos 'any' por simplicidad, ya que la definición de tipos completa de ForceGraphMethods
// genera conflictos con los tipos internos de react-force-graph
import './GraphPage.css';

const GraphPage: React.FC = () => {
  const [graphData, setGraphData] = useState<GraphData>({ nodes: [], links: [] });
  const [selectedNode, setSelectedNode] = useState<GraphNode | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const graphRef = useRef<any>(null);
  
  // Configuración de colores para tipos de nodos
  const nodeColors = {
    concept: '#4285F4',  // azul
    topic: '#34A853',    // verde
    note: '#FBBC05',     // amarillo
    tag: '#EA4335',      // rojo
    default: '#9C27B0'   // morado (para otros tipos)
  };

  // Cargar datos del grafo al cargar el componente
  useEffect(() => {
    const fetchGraphData = async () => {
      try {
        setLoading(true);
        const data = await graphApi.getFullGraph();
        
        // Adaptar los datos al formato esperado por react-force-graph
        const formattedData: GraphData = {
          nodes: data.nodes.map(node => ({
            ...node,
            color: nodeColors[node.type as keyof typeof nodeColors] || nodeColors.default,
            size: 6 // Tamaño base para todos los nodos
          })),
          links: data.links.map(link => ({
            ...link,
            source: link.source,
            target: link.target
          }))
        };
        
        setGraphData(formattedData);
      } catch (err) {
        console.error('Error al cargar datos del grafo:', err);
        setError('No se pudieron cargar los datos del grafo.');
      } finally {
        setLoading(false);
      }
    };

    fetchGraphData();
  }, []);

  // Manejar el clic en un nodo
  const handleNodeClick = useCallback((node: GraphNode) => {
    setSelectedNode(node);
    
    // Expandir el nodo si no está ya expandido
    if (node) {
      expandNode(node.id);
    }
  }, []);

  // Expandir un nodo para mostrar sus vecinos
  const expandNode = async (nodeId: string | number) => {
    try {
      const neighborData = await graphApi.getNodeNeighbors(nodeId);
      
      // Verificar qué nodos y enlaces nuevos hay que añadir
      const existingNodeIds = new Set(graphData.nodes.map(n => n.id));
      const newNodes = neighborData.nodes
        .filter(node => !existingNodeIds.has(node.id))
        .map(node => ({
          ...node,
          color: nodeColors[node.type as keyof typeof nodeColors] || nodeColors.default,
          size: 6
        }));
      
      const existingLinkIds = new Set(graphData.links.map(l => `${l.source}-${l.target}`));
      const newLinks = neighborData.links
        .filter((link: GraphEdge) => !existingLinkIds.has(`${link.source}-${link.target}`))
        .map((link: GraphEdge) => ({
          ...link,
          source: link.source,
          target: link.target
        }));
      
      // Actualizar el estado con los nuevos datos
      if (newNodes.length > 0 || newLinks.length > 0) {
        setGraphData(prevData => ({
          nodes: [...prevData.nodes, ...newNodes],
          links: [...prevData.links, ...newLinks]
        }));
      }
    } catch (err) {
      console.error('Error al expandir nodo:', err);
    }
  };

  // Buscar un nodo y centrarlo en la visualización
  const handleSearchSelect = useCallback((node: GraphNode) => {
    // Verificar si el nodo ya existe en el grafo
    const existingNode = graphData.nodes.find(n => n.id === node.id);
    
    if (existingNode) {
      // Si el nodo ya existe, centrarlo
      if (graphRef.current) {
        graphRef.current.centerAt(existingNode.x, existingNode.y, 1000);
        graphRef.current.zoom(2.5, 1000);
      }
      setSelectedNode(existingNode);
    } else {
      // Si el nodo no existe, cargarlo y sus vecinos
      expandNode(node.id).then(() => {
        // Esperar un momento para que el grafo se actualice y luego intentar centrar
        setTimeout(() => {
          const updatedNode = graphData.nodes.find(n => n.id === node.id);
          if (updatedNode && graphRef.current) {
            graphRef.current.centerAt(updatedNode.x, updatedNode.y, 1000);
            graphRef.current.zoom(2.5, 1000);
          }
          setSelectedNode(updatedNode || null);
        }, 500);
      });
    }
  }, [graphData]);

  // Manejar el reseteo de la vista
  const handleResetView = useCallback(() => {
    if (graphRef.current) {
      graphRef.current.zoomToFit(400);
    }
    setSelectedNode(null);
  }, []);

  if (loading) {
    return (
      <div className="graph-loading">
        <div className="spinner-border text-primary" role="status">
          <span className="visually-hidden">Cargando...</span>
        </div>
        <p className="mt-2">Cargando el mapa mental...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="graph-error">
        <div className="alert alert-danger" role="alert">
          <h4 className="alert-heading">Error</h4>
          <p>{error}</p>
          <hr />
          <button 
            className="btn btn-outline-danger"
            onClick={() => window.location.reload()}
          >
            Reintentar
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="graph-container">
      {/* Controles de zoom */}
      <div className="graph-controls">
        <button 
          className="btn btn-sm btn-outline-primary"
          onClick={() => graphRef.current?.zoom(1.5)}
        >
          <i className="fas fa-search-plus"></i> Zoom +
        </button>
        <button 
          className="btn btn-sm btn-outline-primary mx-2"
          onClick={() => graphRef.current?.zoom(0.67)}
        >
          <i className="fas fa-search-minus"></i> Zoom -
        </button>
        <button 
          className="btn btn-sm btn-outline-secondary"
          onClick={handleResetView}
        >
          <i className="fas fa-sync-alt"></i> Reset
        </button>
      </div>
      
      {/* Componente de búsqueda */}
      <GraphSearch onSelectNode={handleSearchSelect} />
      
      {/* Panel de información del nodo seleccionado */}
      {selectedNode && (
        <NodeInfoPanel 
          node={selectedNode} 
          onClose={() => setSelectedNode(null)} 
        />
      )}
      
      {/* Leyenda de tipos de nodos */}
      <GraphLegend nodeColors={nodeColors} />
      
      {/* Grafo principal */}
      <ForceGraph2D
        ref={graphRef}
        graphData={graphData}
        nodeLabel={(node) => `${(node as GraphNode).label || ''}`}
        linkLabel={(link) => `${(link as GraphEdge).label || ''}`}
        nodeColor={(node) => (node as GraphNode).color || '#ccc'}
        nodeRelSize={6}
        linkWidth={1.5}
        linkDirectionalParticles={2}
        linkDirectionalParticleWidth={2}
        linkCurvature={0.25}
        onNodeClick={handleNodeClick}
        cooldownTicks={100}
        onEngineStop={() => graphRef.current?.zoomToFit(400, 50)}
        width={window.innerWidth}
        height={window.innerHeight - 60} // Dejar espacio para el navbar
      />
    </div>
  );
};

export default GraphPage;
