import apiClient from './client';

// Interfaces para el análisis de texto
export interface TextStats {
  words: number;
  paragraphs: number;
  reading_time: number;
  readability: number;
  avg_words_per_sentence?: number;
  avg_chars_per_word?: number;
}

export interface KeyConcept {
  concept: string;
  frequency: number;
}

export interface TextAnalysisResponse {
  stats: TextStats;
  concepts: KeyConcept[];
  tone: string;
  readability_label: string;
}

export interface TopicDistribution {
  topic: string;
  percentage: number;
}

export interface TopicsAnalysisResponse {
  main_topic: string;
  main_topic_confidence: number;
  topics_distribution: TopicDistribution[];
  suggested_topics: string[];
}

export const analysisApi = {
  // Analizar texto para estadísticas, conceptos, tono, etc.
  analyzeText: async (text: string): Promise<TextAnalysisResponse> => {
    try {
      const response = await apiClient.post('/analysis/text', { text });
      return response.data;
    } catch (error) {
      console.error('Error al analizar texto:', error);
      // Si falla la API, devolvemos un resultado básico
      return {
        stats: {
          words: 0,
          paragraphs: 0,
          reading_time: 0,
          readability: 0
        },
        concepts: [],
        tone: 'Neutral',
        readability_label: 'No disponible'
      };
    }
  },
  
  // Analizar texto para extraer temas relacionados y su distribución
  analyzeTopics: async (text: string, noteId?: number): Promise<TopicsAnalysisResponse> => {
    try {
      const params: any = { text };
      if (noteId) {
        params.note_id = noteId;
      }
      
      const response = await apiClient.post('/analysis/topics', params);
      return response.data;
    } catch (error) {
      console.error('Error al analizar temas:', error);
      // Si falla la API, devolvemos un resultado básico
      return {
        main_topic: '',
        main_topic_confidence: 0,
        topics_distribution: [],
        suggested_topics: []
      };
    }
  }
};
