import apiClient from './client';
import type { OcrResult } from '../types/files';

interface OCROptions {
  engine?: string; // tesseract, easyocr, etc.
  language?: string; // eng, spa, etc.
  preprocessing?: boolean;
}

interface UploadResponseData {
  filename: string;
  path: string;
  mimetype: string;
  size: number;
  thumbnail_url?: string;
  ocr_result?: string;
}

interface GoogleVisionAvailability {
  available: boolean;
}

export const filesApi = {
  uploadFile: async (file: File, options: OCROptions = {}) => {
    const formData = new FormData();
    formData.append('file', file);
    
    if (options.engine) {
      formData.append('engine', options.engine);
    }
    
    if (options.language) {
      formData.append('language', options.language);
    }
    
    if (options.preprocessing !== undefined) {
      formData.append('preprocessing', options.preprocessing.toString());
    }
    
    const response = await apiClient.post('/upload', formData, {
      headers: {
        'Content-Type': 'multipart/form-data'
      }
    });
    
    return response.data as UploadResponseData;
  },
  
  processOCR: async (filePath: string, options: OCROptions = {}): Promise<OcrResult> => {
    const response = await apiClient.post('/process-ocr', {
      file_path: filePath,
      ...options
    });
    
    return response.data as OcrResult;
  },

  checkGoogleVisionAvailable: async (): Promise<boolean> => {
    try {
      const response = await apiClient.get('/files/check-google-vision-available');
      return (response.data as GoogleVisionAvailability).available;
    } catch (error) {
      console.error('Error checking Google Vision availability:', error);
      return false; // Si hay error, asumimos que no está disponible
    }
  },
  
  getAllFiles: async (page: number = 1, perPage: number = 20) => {
    const response = await apiClient.get('/files', { 
      params: { page, per_page: perPage } 
    });
    
    return response.data;
  },
  
  getFileById: async (id: number) => {
    const response = await apiClient.get(`/files/${id}`);
    return response.data;
  },
  
  deleteFile: async (id: number) => {
    const response = await apiClient.delete(`/files/${id}`);
    return response.data;
  },
  
  getFileStatistics: async () => {
    const response = await apiClient.get('/files/statistics');
    return response.data;
  },
  
  createNoteFromOCR: async (ocrResult: string, title: string, options: any = {}) => {
    const response = await apiClient.post('/files/create-note', {
      ocr_result: ocrResult,
      title,
      // Incluir opciones adicionales: is_whiteboard, summary, main_topic, etc.
      ...options
    });
    
    return response.data;
  }
};
