import React from 'react';
import { Link } from 'react-router-dom';

interface Note {
  id: number;
  title: string;
  content: string;
  summary?: string;
  created_at: string;
  updated_at: string;
  user_id: number;
  main_topic?: string;
  source_type?: string;
  tags?: { id: number; name: string }[];
}

interface RecentNotesListProps {
  notes: Note[];
  isLoading: boolean;
  onDeleteNote?: (id: number) => void;
}

const RecentNotesList: React.FC<RecentNotesListProps> = ({
  notes,
  isLoading,
  onDeleteNote
}) => {
  // Formatear fecha para mostrar en formato legible
  const formatDate = (dateString: string): string => {
    const date = new Date(dateString);
    return date.toLocaleDateString();
  };

  // Truncar texto para mostrar un resumen
  const truncateText = (text: string, maxLength: number = 150): string => {
    if (text.length <= maxLength) return text;
    return text.substring(0, maxLength) + '...';
  };

  if (isLoading) {
    return (
      <div className="row" id="notes-container">
        <div className="col-12 text-center py-4">
          <div className="spinner-border text-primary" role="status">
            <span className="visually-hidden">Cargando...</span>
          </div>
          <p className="mt-2">Cargando notas...</p>
        </div>
      </div>
    );
  }

  if (!notes || notes.length === 0) {
    return (
      <div className="row" id="notes-container">
        <div className="col-12 text-center py-4">
          <p>No hay notas disponibles</p>
        </div>
      </div>
    );
  }

  return (
    <div className="row" id="notes-container">
      {notes.map(note => (
        <div className="col-md-6 col-lg-4 mb-4" key={note.id}>
          <div className="card note-card h-100">
            <div className="card-header d-flex justify-content-between align-items-center">
              <h5 className="note-title mb-0">{note.title || 'Sin título'}</h5>
              <div className="dropdown">
                <button className="btn btn-sm btn-link" type="button" data-bs-toggle="dropdown">
                  <i className="fas fa-ellipsis-v"></i>
                </button>
                <ul className="dropdown-menu dropdown-menu-end">
                  <li><Link className="dropdown-item" to={`/notes/${note.id}`}>Ver</Link></li>
                  <li><Link className="dropdown-item" to={`/notes/edit/${note.id}`}>Editar</Link></li>
                  {onDeleteNote && (
                    <>
                      <li><hr className="dropdown-divider" /></li>
                      <li>
                        <button 
                          className="dropdown-item text-danger" 
                          onClick={() => {
                            if (window.confirm('¿Estás seguro de que deseas eliminar esta nota?')) {
                              onDeleteNote(note.id);
                            }
                          }}
                        >
                          Eliminar
                        </button>
                      </li>
                    </>
                  )}
                </ul>
              </div>
            </div>
            <div className="card-body">
              <p className="note-summary">
                {note.summary || truncateText(note.content, 150) || 'Sin contenido'}
              </p>
              {note.main_topic && (
                <span className="note-tag note-topic">{note.main_topic}</span>
              )}
              {note.tags && note.tags.map(tag => (
                <span className="note-tag" key={tag.id}>{tag.name}</span>
              ))}
            </div>
            <div className="card-footer">
              <div className="note-meta">
                <span>{formatDate(note.created_at)}</span>
                <span>{note.source_type || 'Texto'}</span>
              </div>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
};

export default RecentNotesList;
