import React from 'react';
import './Pagination.css';

interface PaginationProps {
  currentPage: number;
  totalPages: number;
  onPageChange: (page: number) => void;
  isLoading?: boolean;
}

const Pagination: React.FC<PaginationProps> = ({
  currentPage,
  totalPages,
  onPageChange,
  isLoading = false
}) => {
  // No mostrar paginación si no hay páginas o solo hay una
  if (totalPages <= 1) {
    return null;
  }

  // Determinar qué páginas mostrar (siempre mostramos primera, última y las cercanas a la actual)
  const getPageNumbers = () => {
    const pageNumbers: (number | string)[] = [];
    
    // Siempre incluir primera página
    pageNumbers.push(1);
    
    // Mostrar elipsis después de la primera página si la página actual está lejos
    if (currentPage > 3) {
      pageNumbers.push('...');
    }
    
    // Mostrar páginas cercanas a la actual
    for (let i = Math.max(2, currentPage - 1); i <= Math.min(totalPages - 1, currentPage + 1); i++) {
      if (i === 1 || i === totalPages) continue; // Ya incluimos primera y última
      pageNumbers.push(i);
    }
    
    // Mostrar elipsis antes de la última página si la página actual está lejos
    if (currentPage < totalPages - 2) {
      pageNumbers.push('...');
    }
    
    // Siempre incluir última página si hay más de una página
    if (totalPages > 1) {
      pageNumbers.push(totalPages);
    }
    
    return pageNumbers;
  };

  return (
    <nav aria-label="Navegación de páginas" className="pagination-container">
      <ul className="pagination justify-content-center">
        {/* Botón Anterior */}
        <li className={`page-item ${currentPage === 1 || isLoading ? 'disabled' : ''}`}>
          <button
            className="page-link"
            onClick={() => onPageChange(currentPage - 1)}
            disabled={currentPage === 1 || isLoading}
            aria-label="Anterior"
          >
            <span aria-hidden="true">&laquo;</span>
          </button>
        </li>
        
        {/* Botones de página */}
        {getPageNumbers().map((page, index) => {
          if (page === '...') {
            return (
              <li key={`ellipsis-${index}`} className="page-item disabled">
                <span className="page-link">...</span>
              </li>
            );
          }
          
          return (
            <li 
              key={page} 
              className={`page-item ${page === currentPage ? 'active' : ''} ${isLoading ? 'disabled' : ''}`}
            >
              <button
                className="page-link"
                onClick={() => onPageChange(page as number)}
                disabled={page === currentPage || isLoading}
              >
                {page}
              </button>
            </li>
          );
        })}
        
        {/* Botón Siguiente */}
        <li className={`page-item ${currentPage === totalPages || isLoading ? 'disabled' : ''}`}>
          <button
            className="page-link"
            onClick={() => onPageChange(currentPage + 1)}
            disabled={currentPage === totalPages || isLoading}
            aria-label="Siguiente"
          >
            <span aria-hidden="true">&raquo;</span>
          </button>
        </li>
      </ul>
      
      {isLoading && (
        <div className="text-center mt-2">
          <div className="spinner-border spinner-border-sm text-primary" role="status">
            <span className="visually-hidden">Cargando...</span>
          </div>
          <span className="ms-2 text-muted small">Cargando página {currentPage}...</span>
        </div>
      )}
    </nav>
  );
};

export default Pagination;
