import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { useAuthStore } from '../../../store/authStore';

// Esquema de validación de contraseña
const passwordSchema = z
  .string()
  .min(8, 'La contraseña debe tener al menos 8 caracteres')
  .refine(
    (password) => /[A-Z]/.test(password),
    { message: 'La contraseña debe contener al menos una letra mayúscula' }
  )
  .refine(
    (password) => /[0-9]/.test(password),
    { message: 'La contraseña debe contener al menos un número' }
  );

// Esquema de validación completo para el formulario de registro
const registerSchema = z.object({
  username: z
    .string()
    .min(3, 'El nombre de usuario debe tener al menos 3 caracteres')
    .regex(/^[a-zA-Z0-9_]+$/, 'Solo se permiten letras, números y guiones bajos'),
  email: z
    .string()
    .email('Ingrese un correo electrónico válido'),
  name: z
    .string()
    .min(2, 'El nombre debe tener al menos 2 caracteres'),
  password: passwordSchema,
  confirmPassword: z.string(),
  acceptTerms: z
    .boolean()
    .refine((value) => value === true, {
      message: 'Debes aceptar los términos y condiciones',
    }),
}).refine((data) => data.password === data.confirmPassword, {
  message: 'Las contraseñas no coinciden',
  path: ['confirmPassword'],
});

// Tipo derivado del esquema
type RegisterFormValues = z.infer<typeof registerSchema>;

const RegisterForm = () => {
  const navigate = useNavigate();
  const { register: registerUser, error, clearError, isLoading } = useAuthStore();
  
  const { register, handleSubmit, formState: { errors } } = useForm<RegisterFormValues>({
    resolver: zodResolver(registerSchema),
    defaultValues: {
      acceptTerms: false,
    },
  });

  // Estado para mostrar mensajes de éxito
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  const onSubmit = async (data: RegisterFormValues) => {
    // Eliminar confirmPassword y acceptTerms antes de enviar
    const { confirmPassword, acceptTerms, ...userData } = data;
    
    clearError(); // Limpiar errores previos
    console.log('Iniciando registro con datos:', { ...userData, password: '[OCULTO]' });
    
    try {
      console.log('Llamando a función registerUser del authStore...');
      await registerUser(userData);
      console.log('Registro completado con éxito');
      setSuccessMessage('Registro exitoso. Ahora puedes iniciar sesión.');
      
      // Redirigir al login después de 2 segundos
      setTimeout(() => {
        console.log('Redirigiendo a login...');
        navigate('/login');
      }, 2000);
    } catch (error) {
      console.error('Error durante el registro:', error);
    }
  };

  return (
    <div className="register-form">
      <h2>Crear una nueva cuenta</h2>
      
      {error && (
        <div className="error-message">
          {error}
          <button onClick={clearError} className="close-btn">×</button>
        </div>
      )}
      
      {successMessage && (
        <div className="success-message">
          {successMessage}
        </div>
      )}
      
      <form onSubmit={(e) => {
          e.preventDefault();
          console.log('Formulario de registro enviado');
          handleSubmit(onSubmit)(e);
        }}>
        <div className="form-group">
          <label htmlFor="username">Nombre de usuario*</label>
          <input
            id="username"
            type="text"
            {...register('username')}
            placeholder="Ingrese un nombre de usuario único"
            className={errors.username ? 'input-error' : ''}
          />
          {errors.username && <span className="error">{errors.username.message}</span>}
        </div>
        
        <div className="form-group">
          <label htmlFor="email">Correo electrónico*</label>
          <input
            id="email"
            type="email"
            {...register('email')}
            placeholder="ejemplo@correo.com"
            className={errors.email ? 'input-error' : ''}
          />
          {errors.email && <span className="error">{errors.email.message}</span>}
        </div>
        
        <div className="form-group">
          <label htmlFor="name">Nombre completo*</label>
          <input
            id="name"
            type="text"
            {...register('name')}
            placeholder="Su nombre completo"
            className={errors.name ? 'input-error' : ''}
          />
          {errors.name && <span className="error">{errors.name.message}</span>}
        </div>
        
        <div className="form-group">
          <label htmlFor="password">Contraseña*</label>
          <input
            id="password"
            type="password"
            {...register('password')}
            placeholder="********"
            className={errors.password ? 'input-error' : ''}
          />
          {errors.password && <span className="error">{errors.password.message}</span>}
          <div className="password-requirements">
            <p>La contraseña debe tener:</p>
            <ul>
              <li>Al menos 8 caracteres</li>
              <li>Al menos una letra mayúscula</li>
              <li>Al menos un número</li>
            </ul>
          </div>
        </div>
        
        <div className="form-group">
          <label htmlFor="confirmPassword">Confirmar contraseña*</label>
          <input
            id="confirmPassword"
            type="password"
            {...register('confirmPassword')}
            placeholder="********"
            className={errors.confirmPassword ? 'input-error' : ''}
          />
          {errors.confirmPassword && <span className="error">{errors.confirmPassword.message}</span>}
        </div>
        
        <div className="form-group checkbox">
          <input
            id="acceptTerms"
            type="checkbox"
            {...register('acceptTerms')}
          />
          <label htmlFor="acceptTerms">
            Acepto los <a href="#">términos y condiciones</a>
          </label>
          {errors.acceptTerms && <span className="error">{errors.acceptTerms.message}</span>}
        </div>
        
        <div className="form-actions">
          <button type="submit" disabled={isLoading} className="btn-primary">
            {isLoading ? 'Registrando...' : 'Registrarse'}
          </button>
        </div>
        
        <div className="links">
          <p>
            ¿Ya tienes una cuenta? <a href="#" onClick={(e) => { e.preventDefault(); navigate('/login'); }}>Iniciar sesión</a>
          </p>
        </div>
      </form>
    </div>
  );
};

export default RegisterForm;
