import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { authApi } from '../../../api/auth';
import './Auth.css';

// Definir pasos del formulario como constantes numéricas en lugar de enum
const RecoveryStep = {
  USERNAME: 0,
  SECURITY_QUESTION: 1,
  NEW_PASSWORD: 2,
  SUCCESS: 3
} as const;

type RecoveryStepType = typeof RecoveryStep[keyof typeof RecoveryStep];

// Esquema para validar nombre de usuario
const usernameSchema = z.object({
  username: z.string().min(1, 'El nombre de usuario es requerido')
});

// Esquema para validar respuesta de seguridad
const answerSchema = z.object({
  answer: z.string().min(1, 'La respuesta es requerida')
});

// Esquema para validar nueva contraseña (igual que en registro)
const passwordSchema = z.object({
  password: z
    .string()
    .min(8, 'La contraseña debe tener al menos 8 caracteres')
    .refine(
      (password) => /[A-Z]/.test(password),
      { message: 'La contraseña debe contener al menos una letra mayúscula' }
    )
    .refine(
      (password) => /[0-9]/.test(password),
      { message: 'La contraseña debe contener al menos un número' }
    ),
  confirmPassword: z.string()
}).refine((data) => data.password === data.confirmPassword, {
  message: 'Las contraseñas no coinciden',
  path: ['confirmPassword']
});

// Tipos para los formularios
type UsernameFormValues = z.infer<typeof usernameSchema>;
type AnswerFormValues = z.infer<typeof answerSchema>;
type PasswordFormValues = z.infer<typeof passwordSchema>;

const PasswordRecoveryForm = () => {
  const navigate = useNavigate();
  const [currentStep, setCurrentStep] = useState<RecoveryStepType>(RecoveryStep.USERNAME);
  const [username, setUsername] = useState<string>('');
  const [securityQuestion, setSecurityQuestion] = useState<string>('');
  const [error, setError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  
  // Form para el paso de introducir username
  const usernameForm = useForm<UsernameFormValues>({
    resolver: zodResolver(usernameSchema)
  });
  
  // Form para el paso de responder pregunta de seguridad
  const answerForm = useForm<AnswerFormValues>({
    resolver: zodResolver(answerSchema)
  });
  
  // Form para el paso de nueva contraseña
  const passwordForm = useForm<PasswordFormValues>({
    resolver: zodResolver(passwordSchema)
  });
  
  // Manejar envío del formulario de nombre de usuario
  const handleUsernameSubmit = async (data: UsernameFormValues) => {
    setIsLoading(true);
    setError(null);
    
    try {
      // Obtener pregunta de seguridad desde la API
      const response = await authApi.getSecurityQuestion(data.username);
      setUsername(data.username);
      setSecurityQuestion(response.security_question);
      setCurrentStep(RecoveryStep.SECURITY_QUESTION);
    } catch (err: any) {
      setError(err.response?.data?.error || 'No se pudo obtener la pregunta de seguridad');
    } finally {
      setIsLoading(false);
    }
  };
  
  // Manejar envío del formulario de respuesta de seguridad
  const handleAnswerSubmit = async () => {
    // Aquí solo avanzamos al siguiente paso, la validación se hace junto con la nueva contraseña
    setCurrentStep(RecoveryStep.NEW_PASSWORD);
  };
  
  // Manejar envío del formulario de nueva contraseña
  const handlePasswordSubmit = async (data: PasswordFormValues) => {
    setIsLoading(true);
    setError(null);
    
    try {
      // Recuperar contraseña con respuesta de seguridad
      await authApi.resetPasswordWithAnswer({
        username: username,
        answer: answerForm.getValues().answer,
        new_password: data.password
      });
      
      // Avanzar al paso final (éxito)
      setCurrentStep(RecoveryStep.SUCCESS);
    } catch (err: any) {
      setError(err.response?.data?.error || 'Error al restablecer la contraseña');
    } finally {
      setIsLoading(false);
    }
  };
  
  // Manejar click en botón de redirección al login
  const handleLoginRedirect = () => {
    navigate('/login');
  };
  
  // Mostrar el paso actual según el estado
  const renderCurrentStep = () => {
    switch (currentStep) {
      case RecoveryStep.USERNAME:
        return (
          <form onSubmit={usernameForm.handleSubmit(handleUsernameSubmit)}>
            <div className="form-group">
              <label htmlFor="username">Nombre de usuario</label>
              <input
                id="username"
                type="text"
                {...usernameForm.register('username')}
                className={usernameForm.formState.errors.username ? 'input-error' : ''}
                placeholder="Ingrese su nombre de usuario"
              />
              {usernameForm.formState.errors.username && (
                <span className="error">{usernameForm.formState.errors.username.message}</span>
              )}
            </div>
            
            <div className="form-actions">
              <button 
                type="submit" 
                disabled={isLoading}
                className="btn-primary"
              >
                {isLoading ? 'Verificando...' : 'Continuar'}
              </button>
            </div>
          </form>
        );
        
      case RecoveryStep.SECURITY_QUESTION:
        return (
          <form onSubmit={answerForm.handleSubmit(handleAnswerSubmit)}>
            <div className="security-question">
              <p><strong>Pregunta de seguridad:</strong></p>
              <p>{securityQuestion}</p>
            </div>
            
            <div className="form-group">
              <label htmlFor="answer">Tu respuesta</label>
              <input
                id="answer"
                type="text"
                {...answerForm.register('answer')}
                className={answerForm.formState.errors.answer ? 'input-error' : ''}
                placeholder="Ingrese su respuesta"
              />
              {answerForm.formState.errors.answer && (
                <span className="error">{answerForm.formState.errors.answer.message}</span>
              )}
            </div>
            
            <div className="form-actions">
              <button 
                type="button" 
                onClick={() => setCurrentStep(RecoveryStep.USERNAME)}
                className="btn-secondary"
              >
                Atrás
              </button>
              <button 
                type="submit" 
                disabled={isLoading}
                className="btn-primary"
              >
                Continuar
              </button>
            </div>
          </form>
        );
        
      case RecoveryStep.NEW_PASSWORD:
        return (
          <form onSubmit={passwordForm.handleSubmit(handlePasswordSubmit)}>
            <div className="form-group">
              <label htmlFor="password">Nueva contraseña</label>
              <input
                id="password"
                type="password"
                {...passwordForm.register('password')}
                className={passwordForm.formState.errors.password ? 'input-error' : ''}
                placeholder="********"
              />
              {passwordForm.formState.errors.password && (
                <span className="error">{passwordForm.formState.errors.password.message}</span>
              )}
              <div className="password-requirements">
                <p>La contraseña debe tener:</p>
                <ul>
                  <li>Al menos 8 caracteres</li>
                  <li>Al menos una letra mayúscula</li>
                  <li>Al menos un número</li>
                </ul>
              </div>
            </div>
            
            <div className="form-group">
              <label htmlFor="confirmPassword">Confirmar contraseña</label>
              <input
                id="confirmPassword"
                type="password"
                {...passwordForm.register('confirmPassword')}
                className={passwordForm.formState.errors.confirmPassword ? 'input-error' : ''}
                placeholder="********"
              />
              {passwordForm.formState.errors.confirmPassword && (
                <span className="error">{passwordForm.formState.errors.confirmPassword.message}</span>
              )}
            </div>
            
            <div className="form-actions">
              <button 
                type="button" 
                onClick={() => setCurrentStep(RecoveryStep.SECURITY_QUESTION)}
                className="btn-secondary"
              >
                Atrás
              </button>
              <button 
                type="submit" 
                disabled={isLoading}
                className="btn-primary"
              >
                {isLoading ? 'Restableciendo...' : 'Restablecer contraseña'}
              </button>
            </div>
          </form>
        );
        
      case RecoveryStep.SUCCESS:
        return (
          <div className="success-step">
            <div className="success-message">
              <p>¡Tu contraseña ha sido restablecida exitosamente!</p>
              <p>Ya puedes iniciar sesión con tu nueva contraseña.</p>
            </div>
            
            <div className="form-actions">
              <button 
                type="button" 
                onClick={handleLoginRedirect}
                className="btn-primary"
              >
                Ir al inicio de sesión
              </button>
            </div>
          </div>
        );
    }
  };

  return (
    <div className="password-recovery-form">
      <h2>Recuperar Contraseña</h2>
      
      {error && (
        <div className="error-message">
          {error}
          <button onClick={() => setError(null)} className="close-btn">×</button>
        </div>
      )}
      
      {/* Paso a paso de recuperación */}
      <div className="recovery-steps">
        <div className={`step ${currentStep >= RecoveryStep.USERNAME ? 'active' : ''}`}>
          <span className="step-number">1</span>
          <span className="step-text">Usuario</span>
        </div>
        <div className={`step ${currentStep >= RecoveryStep.SECURITY_QUESTION ? 'active' : ''}`}>
          <span className="step-number">2</span>
          <span className="step-text">Pregunta</span>
        </div>
        <div className={`step ${currentStep >= RecoveryStep.NEW_PASSWORD ? 'active' : ''}`}>
          <span className="step-number">3</span>
          <span className="step-text">Contraseña</span>
        </div>
      </div>
      
      {renderCurrentStep()}
      
      <div className="links">
        <p>
          <a href="#" onClick={(e) => { e.preventDefault(); navigate('/login'); }}>
            Volver al inicio de sesión
          </a>
        </p>
      </div>
    </div>
  );
};

export default PasswordRecoveryForm;
